function migrateCoachTreeV2(){
 state.headCoach??={level:1,xp:0,skillPoints:1,skills:{}};state.headCoach.skills??={};
 if(Number(state.headCoach.treeVersion||0)>=2)return;
 // Legacy Program CEO saves predate the new CEO root. Grant only the new root
 // so the already-paid legacy skill remains connected instead of resetting it.
 if(state.headCoach.skills.CEO)state.headCoach.skills.CEO_FOUNDATION=true;
 state.headCoach.treeVersion=2;state.headCoach.activeBranch=COACH_BRANCHES[state.headCoach.activeBranch]?state.headCoach.activeBranch:"Recruiter";
}
