function coachRecruitingMult(r=null,context={}){let pct=coachEffect("recruitingActionPct")+Number(window.SDF_V188?.cultureRecruitingPct?.()||0);if(r&&state.school?.pipelines?.includes?.(r.home))pct+=coachEffect("pipelineRecruitingPct");if(context.lateClose)pct+=coachEffect("lateCloseRecruitingPct");return(1+pct)*Number(window.SDF_V189?.recruitingMultiplier?.(r)||1)*Number(window.SDF_V190?.recruitingMultiplier?.(r)||1)*Number(window.SDF_V191?.recruitingMultiplier?.(r)||1)*Number(window.SDF_V193?.recruitingMultiplier?.(r)||1)}
function coachPracticeBonus(){return 1+coachEffect("practiceEffectPct")}
function coachInjuryMult(){return clamp(1-coachEffect("injuryReduction"),.45,1)}
