window.coachMoraleDelta=coachMoraleDelta;
function applyYoungPlayerPracticeDevelopment(){
 if(state.weeklyPractice!=="Young Player Development")return 0;const extraSlots=Math.round(coachEffect("backupPracticeSlots")),chance=clamp(.45+coachEffect("backupPracticeChance"),.05,.90),young=state.roster.filter(p=>p.year<=2&&!p.starter&&!p.redshirt&&!p.injury&&p.ovr<p.pot).sort((a,b)=>(b.pot-b.ovr)-(a.pot-a.ovr)).slice(0,2+extraSlots);let gains=0;
 young.forEach(p=>{if((window.SDF_SEEDS?.random()??Math.random())<chance){p.ovr=clamp(Math.min(p.pot,p.ovr+1),45,99);p.weeklyDevelopment=(p.weeklyDevelopment||0)+1;gains++;state.news.push(`${p.name} gained +1 OVR from the young-player practice focus.`)}});return gains
}
