function coachEffectLabels(skill){const e=skill.effects||{},out=[];if(e.recruitingActionPct)out.push(`Recruit actions +${Math.round(e.recruitingActionPct*100)}%`);if(e.scoutConfidenceBonus)out.push(`Scout confidence +${e.scoutConfidenceBonus}`);if(e.distancePenaltyReduction)out.push(`Distance penalty -${Math.round(e.distancePenaltyReduction*100)}%`);if(e.pipelineRecruitingPct)out.push(`Pipeline influence +${Math.round(e.pipelineRecruitingPct*100)}%`);if(e.pipelineGrowthPct)out.push(`Pipeline growth +${Math.round(e.pipelineGrowthPct*100)}%`);if(e.youngProgressionBonus)out.push(`Young offseason growth +${e.youngProgressionBonus}`);if(e.progressionChance)out.push(`Extra progression chance +${Math.round(e.progressionChance*100)}%`);if(e.injuryReduction)out.push(`Injury risk -${Math.round(e.injuryReduction*100)}%`);if(e.practiceEffectPct)out.push(`Practice effect +${Math.round(e.practiceEffectPct*100)}%`);if(e.fourthDownSuccessPct)out.push(`4th-down success +${Math.round(e.fourthDownSuccessPct*100)}%`);if(e.portalRiskReduction)out.push(`Portal risk -${Math.round(e.portalRiskReduction*100)}%`);if(e.promiseInfluencePct)out.push(`Promise influence +${Math.round(e.promiseInfluencePct*100)}%`);if(e.promiseTrustGainPct)out.push(`Kept-promise trust +${Math.round(e.promiseTrustGainPct*100)}%`);if(e.staffRetentionPct)out.push(`Staff poach risk -${Math.round(e.staffRetentionPct*100)}%`);if(e.annualAllocationPct)out.push(`Annual allocation +${Math.round(e.annualAllocationPct*100)}%`);if(e.recruitContactCapAll)out.push(`Weekly contact cap +${e.recruitContactCapAll} hrs`);if(e.recruitContactCapSpecialty)out.push(`HC specialty cap +${e.recruitContactCapSpecialty} hrs`);return out.slice(0,4)}
function renderCoachTab(){
 if(!$("coachSkillTree"))return;ensureV9State();syncHeadCoachRatings();const head=state.staff?.head||{},active=COACH_BRANCHES[state.headCoach.activeBranch]?state.headCoach.activeBranch:"Recruiter",branch=COACH_BRANCHES[active],skills=HEAD_COACH_SKILLS.filter(s=>s.branch===active),unlockedTotal=HEAD_COACH_SKILLS.filter(s=>hasCoachSkill(s.id)).length,xpNeed=state.headCoach.level*100,xpPct=clamp(Math.round(state.headCoach.xp/Math.max(1,xpNeed)*100),0,100);
 $("coachSkillSummary").innerHTML=`<div class="coach-summary-strip"><div><small>LEVEL</small><b>${state.headCoach.level}</b></div><div><small>SKILL POINTS</small><b>${state.headCoach.skillPoints}</b></div><div><small>UNLOCKED</small><b>${unlockedTotal}/${HEAD_COACH_SKILLS.length}</b></div><div><small>IDENTITY</small><b>${COACH_BRANCHES[coachDominantBranch()].label}</b></div></div>`;
 const tabs=Object.entries(COACH_BRANCHES).map(([key,b])=>{const n=HEAD_COACH_SKILLS.filter(s=>s.branch===key&&hasCoachSkill(s.id)).length,total=HEAD_COACH_SKILLS.filter(s=>s.branch===key).length;return`<button class="coach-branch-tab ${key===active?'active':''}" onclick="selectCoachBranch('${key}')"><span>${b.icon}</span><b>${b.label}</b><small>${n}/${total}</small></button>`}).join("");
 const tiers=[1,2,3,4].map(t=>{const nodes=skills.filter(s=>s.tier===t);return`<div class="coach-tier-row" data-tier="${t}">${nodes.map(s=>{const unlocked=hasCoachSkill(s.id),prereq=s.requires.every(hasCoachSkill),affordable=state.headCoach.skillPoints>=s.cost,available=!unlocked&&prereq&&affordable,missing=s.requires.filter(x=>!hasCoachSkill(x)).map(x=>coachSkillById(x)?.name).filter(Boolean),labels=coachEffectLabels(s);return`<article class="coach-skill-card ${unlocked?'unlocked':prereq?'available-path':'locked'}"><div class="coach-skill-top"><span class="coach-tier-pill">TIER ${s.tier}</span><span class="coach-cost">${s.cost} SP</span></div><h3>${s.name}</h3><p>${s.desc}</p>${labels.length?`<div class="coach-effect-chips">${labels.map(x=>`<span>${x}</span>`).join('')}</div>`:''}<small class="coach-requires">${s.requires.length?(missing.length?`Needs ${missing.join(' + ')}`:`Prerequisites complete`):'Starting node'}</small><button class="btn ${unlocked?'success':'primary'} full" onclick="unlockCoachSkill('${s.id}')" ${unlocked||!available?'disabled':''}>${unlocked?'Unlocked':!prereq?'Locked':!affordable?`Need ${s.cost} SP`:'Unlock Skill'}</button></article>`}).join('')}</div>`}).join("");
 $("coachSkillTree").innerHTML=`<section class="coach-tree-v2"><div class="coach-identity-card"><div><span class="eyebrow">HEAD COACH DEVELOPMENT</span><h2>${state.coachCareer?.name||head.name||'Head Coach'}</h2><p>${branch.icon} <b>${branch.label}</b> — ${branch.tagline}</p></div><div class="coach-ratings"><div><small>REC</small><b>${head.recruiting||0}</b></div><div><small>DEV</small><b>${head.development||0}</b></div><div><small>GAME</small><b>${head.game||0}</b></div></div></div><div class="coach-xp"><span>Level ${state.headCoach.level} progress</span><b>${state.headCoach.xp}/${xpNeed} XP</b><div><i style="width:${xpPct}%"></i></div></div><nav class="coach-branch-tabs">${tabs}</nav><div class="coach-branch-head"><span>${branch.icon}</span><div><h2>${branch.label}</h2><p>${branch.tagline}</p></div></div><div class="coach-tier-track">${tiers}</div></section>`;
 renderLeadershipPanel()
}
function initializeDepthChart(){
 ensureV9State();POSITIONS.forEach(pos=>{let eligible=state.roster.filter(p=>p.pos===pos&&!p.redshirt).sort((a,b)=>b.ovr-a.ovr);state.depthChart[pos]??={slots:eligible.slice(0,3).map((p,i)=>({playerId:p.id,snapShare:i===0?70:i===1?25:5}))}})
}
function normalizeSnapShares(pos){
 let slots=state.depthChart[pos]?.slots||[],total=slots.reduce((n,s)=>n+Number(s.snapShare||0),0);if(!total)return;slots.forEach(s=>s.snapShare=Math.round(Number(s.snapShare||0)/total*100))
}
function setDepthPlayer(pos,index,id){initializeDepthChart();state.depthChart[pos].slots[index]??={playerId:null,snapShare:0};state.depthChart[pos].slots[index].playerId=id;applyDepthChart();renderDepthManager()}
function setSnapShare(pos,index,value){initializeDepthChart();state.depthChart[pos].slots[index].snapShare=clamp(Number(value)||0,0,100);normalizeSnapShares(pos);applyDepthChart();renderDepthManager()}
window.setDepthPlayer=setDepthPlayer;window.setSnapShare=setSnapShare;
function applyDepthChart(){
 state.roster.forEach(p=>p.starter=false);Object.values(state.depthChart).forEach(d=>{let first=d.slots?.[0];if(first){let p=state.roster.find(x=>x.id===first.playerId);if(p)p.starter=true}})
}
