 if(rb){let s=ensurePlayerStats(rb),att=rand(12,27),yds=clamp(rand(45,145)+Math.round((rb.ovr-g.oppPower)/3),10,230),td=Math.max(0,Math.min(4,Math.round((us-passTD*7)/14)+rand(0,1)));Object.assign(s,{games:s.games+1,rushAtt:s.rushAtt+att,rushYds:s.rushYds+yds,rushTD:s.rushTD+td,rec:s.rec+rand(0,5),recYds:s.recYds+rand(0,55)});recordPlayerGame(rb,state.week,g.opponent,win?"W":"L",{rushYds:yds,rushTD:td})}
 let remaining=passYds;
 wrs.forEach((p,i)=>{let s=ensurePlayerStats(p),share=i===0?.34:i===1?.26:i===2?.2:.12,yds=i===wrs.length-1?Math.max(0,remaining):Math.round(passYds*share),rec=clamp(Math.round(yds/rand(9,16)),0,12),td=i<passTD?1:(window.SDF_SEEDS?.random()??Math.random())<.12?1:0;remaining-=yds;Object.assign(s,{games:s.games+1,rec:s.rec+rec,recYds:s.recYds+yds,recTD:s.recTD+td});recordPlayerGame(p,state.week,g.opponent,win?"W":"L",{rec,recYds:yds,recTD:td})});
 defenders.forEach(p=>{let s=ensurePlayerStats(p),t=rand(2,11),tfl=(window.SDF_SEEDS?.random()??Math.random())<.45?rand(0,3):0,sacks=["EDGE","DL","LB"].includes(p.pos)&&(window.SDF_SEEDS?.random()??Math.random())<.3?rand(0,2):0,ints=["CB","S","LB"].includes(p.pos)&&(window.SDF_SEEDS?.random()??Math.random())<.12?1:0;Object.assign(s,{games:s.games+1,tackles:s.tackles+t,tfl:s.tfl+tfl,sacks:s.sacks+sacks,defINT:s.defINT+ints,ff:s.ff+((window.SDF_SEEDS?.random()??Math.random())<.05?1:0)});recordPlayerGame(p,state.week,g.opponent,win?"W":"L",{tackles:t,tfl,sacks,defINT:ints})});
