function historicalClassLabel(p,h,index,history){
 if(h?.classLabel)return h.classLabel;if(Number(h?.classYear)>=1&&Number(h.classYear)<=4)return ['Freshman','Sophomore','Junior','Senior'][Number(h.classYear)-1];const progression=(p.progressionHistory||[]).find(x=>Number(x.dynastyYear)===Number(h?.year));if(progression?.classBefore)return progression.classBefore;const inferred=Math.max(1,Math.min(4,Number(p.year||1)-(history.length-index)));return ['Freshman','Sophomore','Junior','Senior'][inferred-1]||`Year ${inferred}`
}
