   // caused visible UI stalls. Manual/backup saves and a periodic integrity
   // check still perform the original full round-trip verification.
   const fullVerify=manual||backup||Date.now()-lastFullSaveVerificationAt>=60000;
   if(fullVerify){verified=nativeReadSlot(slot,false);if(!verified||verified.length!==json.length)throw new Error('Android save verification failed');JSON.parse(verified);lastFullSaveVerificationAt=Date.now()}
