function recruitButtons(r,status,compact=false){
 const cls=compact?'':' small';
 return`<button class="btn${cls} neutral" onclick="toggleBoard('${r.id}')" ${(!r.onBoard&&status.boardFull)||!status.canEvaluate?'disabled':''}>${r.onBoard?'Remove':'Board'}</button><button class="btn${cls} neutral" onclick="offer('${r.id}')" ${!status.canRecruit||r.offered||state.scholarships<=0?'disabled':''}>${r.offered?'Offered':'Scholarship'}</button><button class="btn${cls} neutral" onclick="scout('${r.id}')" ${!status.canEvaluate||r.scouted||state.weeklyHours<8?'disabled':''}>Scout (8 hrs)</button>${actionButtons(r,status,compact)}<button class="btn${cls} success" onclick="openRecruit('${r.id}')">Profile</button>${nilButton(r,status,compact)}`
}
function lateOpportunity(r){
 if(r.committedTo)return false;if(Number(r.entryWeek||1)>1&&state.week-Number(r.entryWeek||1)<=2)return true;const rc=race(r),offers=rc.entries.filter(e=>e.offered).length,user=rc.user;
 if(r.stars===2&&state.week>=4)return true;return state.week>=3&&!statusFor(r).lockedOut&&(rc.leader?.score<78||offers<=3||(user&&user.rank<=10&&rc.gap<=16))
}
function recruitableNow(r){
 const s=statusFor(r);
 // Recruit-specific eligibility only. Global board/class capacity should not hide the entire pool.
 return !r.committedTo&&s.access.allowed&&!s.lockedOut&&!s.eligibility.locked
}
function filteredProspects(){
 const n=recruitRenderNeeds(),q=(document.getElementById('recruitSearch')?.value||'').trim().toLowerCase(),pos=$('positionFilter').value,starFilter=$('starFilter').value,region=$('recruitRegionFilter').value,status=$('statusFilter').value,sort=$('sortFilter').value;
 const list=state.recruits.filter(r=>{ensureRecruit(r);return(!q||`${r.name} ${r.city} ${r.home} ${r.pos}`.toLowerCase().includes(q))&&(pos==='ALL'||r.pos===pos)&&(starFilter==='ALL'||r.stars===Number(starFilter))&&(region==='ALL'||r.region===region)&&(status==='AVAILABLE'?!r.committedTo:status==='RECRUITABLE'?recruitableNow(r):status==='UNCONTACTED'?!r.committedTo&&!r.onBoard&&!r.offered&&Number(r.recruitInfluence?.[USER_ID()]||0)===0:status==='LATE'?lateOpportunity(r):status==='BOARD'?r.onBoard&&!r.committedTo:status==='OFFERED'?r.offered&&!r.committedTo:!!r.committedTo)});
 if(sort==='INTEREST')list.sort((a,b)=>(race(a).user?.rank||99)-(race(b).user?.rank||99)||(race(b).user?.score||0)-(race(a).user?.score||0));
 else if(sort==='NEED')list.sort((a,b)=>n[b.pos].sev-n[a.pos].sev||a.rank-b.rank);
 else if(sort==='DISTANCE')list.sort((a,b)=>distance(state.school,a)-distance(state.school,b));
 else if(sort==='FIT')list.sort((a,b)=>weightedFit(b,state.school)-weightedFit(a,state.school));
 else list.sort((a,b)=>a.rank-b.rank);return list
}
function recruitingOverviewHtml(){const board=state.recruits.filter(r=>r.onBoard&&!r.committedTo).length,led=state.recruits.filter(r=>r.onBoard&&!r.committedTo&&race(r).user?.rank===1).length;return metric('Weekly Recruiting Hours',state.weeklyHours)+metric('Open Prospects',state.recruits.filter(r=>!r.committedTo).length)+metric('Recruitable Now',state.recruits.filter(recruitableNow).length)+metric('Recruiting Board',`${board}/${RECRUIT_BOARD_LIMIT}`)+metric('Board Slots',Math.max(0,RECRUIT_BOARD_LIMIT-board))+metric('Offers Left',state.scholarships)+metric('Signed Class',`${state.commits.length}/${CLASS_SIGNING_LIMIT}`)+metric('Battles Led',led)+metric('Late Opportunities',state.recruits.filter(lateOpportunity).length)+metric('Recruiting NIL Pool',formatNilMoney(state.nilBudget))+metric('NIL Offered',formatNilMoney(nilCommittedTotal()))+metric('Program Funds',formatNilMoney(state.budget))+metric('Recruiting Phase',state.recruitingPhase)}
function recruitTableRowHtml(r){const n=recruitRenderNeeds(),status=statusFor(r),reason=status.canRecruit?status.warning:status.activeReason;return`<tr data-recruit-id="${r.id}" class="${!status.canRecruit?'recruit-blocked':''}"><td>${r.rank}</td><td><button class="link-button" onclick="openRecruit('${r.id}')">${r.name}</button><span class="sub">${r.arch} · ${r.personality}</span><div class="motivation-inline">${r.motivations.slice(0,2).map(m=>`<span>${m.label}</span>`).join('')}</div><span class="sub recruit-contact-remaining">${contactHoursLeft(r)}/${contactCapFor(r)} hrs remaining</span></td><td>${r.pos}</td><td class="star">${star(r.stars)}${!status.access.allowed?'<span class="lock-badge">TIER</span>':status.lockedOut?'<span class="lock-badge">CUT</span>':status.eligibility.locked?'<span class="lock-badge">DEALBREAKER</span>':''}</td><td>${r.city}, ${r.home}<span class="sub">${distance(state.school,r)} mi${state.school.pipelines.includes(r.home)?' · PIPELINE':''}</span></td><td><span class="stage">${stageFor(r)}</span></td><td>${r.scouted?r.ovr:'??'}</td><td>${projectedRecruitUpside(r)}</td><td>${r.scouted?(r.scoutConfidence||0)+'%':'—'}</td><td>${n[r.pos].label}<span class="sub">PT grade ${letterGrade(playingTimeGrade(r,state.school))}</span></td><td><span class="dealbreaker-badge">${dealbreakerDisplay(r)}</span></td><td><div class="race-summary">${userRaceSummary(r)}<div class="race-compact">${raceCompact(r,3)}</div></div>${reason?`<span class="sub ineligible">${reason}</span>`:''}</td><td>${planSelect(r,status)}</td><td><div class="actions">${recruitButtons(r,status)}</div></td></tr>`}
function recruitMobileCardHtml(r){const status=statusFor(r),rc=race(r),notice=status.canRecruit?status.warning:status.activeReason;return`<article data-recruit-id="${r.id}" class="mobile-data-card ${!status.canRecruit?'recruit-blocked':''}"><div class="mobile-data-head"><div><h3>#${r.rank} ${r.name}</h3><span class="sub">${r.pos} · ${r.arch} · ${r.city}, ${r.home}</span><span class="sub recruit-contact-remaining">${contactHoursLeft(r)}/${contactCapFor(r)} hrs remaining</span></div><span class="star">${star(r.stars)}</span></div><div class="motivation-row">${motivationChips(r)}</div><div class="mobile-data-grid"><div><small>YOUR RANK</small><b>#${rc.user?.rank||'—'}</b></div><div><small>YOUR INTEREST</small><b>${Math.round(rc.user?.score||0)}</b></div><div><small>LEADER</small><b>${rc.leader?.school.name||'—'}</b></div><div><small>FIT</small><b>${rc.user?.grade||'—'}</b></div><div><small>PLAYING TIME</small><b>${letterGrade(playingTimeGrade(r,state.school))}</b></div><div><small>NIL ASK</small><b>${formatNilMoney(nilOfferAmount(r))}</b></div><div><small>CONTACT HRS LEFT</small><b>${contactHoursLeft(r)} / ${contactCapFor(r)}</b></div></div><div class="mobile-race-list">${raceCompact(r,5)}</div>${notice?`<div class="recruit-status-message ${status.canRecruit?'warning':''}"><b>${status.canRecruit?'Dealbreaker warning':'Active recruiting locked'}</b><span>${notice}</span></div>`:planSelect(r,status)}${window.SDF_DYNASTY_STORY?.recruitCardHtml?.(r)||''}<div class="mobile-actions">${recruitButtons(r,status,true)}</div></article>`}
function renderRecruitSummary(){return withRecruitReadFrame(renderRecruitSummaryContents)}
function renderRecruitSummaryContents(){const overview=$('recruitingOverview');if(overview&&!overview.closest('details:not([open])'))overview.innerHTML=recruitingOverviewHtml();if($('hoursLabel'))$('hoursLabel').textContent=state.weeklyHours;if($('scholarshipLabel'))$('scholarshipLabel').textContent=state.scholarships;const ca=Math.round(avg(state.commits.map(r=>r.ovr))||0),score=Math.round(state.commits.reduce((s,r)=>s+r.ovr+r.stars*5+(r.pot||r.ovr)*.2,0));if($('classCards'))$('classCards').innerHTML=metric('Commits',state.commits.length)+metric('Average OVR',ca||'—')+metric('5-stars',state.commits.filter(r=>r.stars===5).length)+metric('Class Score',score);if($('commitList'))$('commitList').innerHTML=state.commits.map(r=>`<div class="commit-card"><h4>${r.name}</h4><div>${r.pos} · ${r.arch} · <span class="star">${star(r.stars)}</span></div><span class="sub">${r.city}, ${r.home} · OVR ${r.ovr} · ${state.signingDayResolved?`POT ${r.truePot||r.pot||'?'}`:`Projected Upside ${projectedRecruitUpside(r)}`}</span></div>`).join('')||'<p class="muted">No commitments yet.</p>'}
function updateRecruitCard(id){const selector=`#recruitCardList [data-recruit-id="${CSS.escape(String(id))}"]`,old=document.querySelector?.(selector),top=old?.getBoundingClientRect?.().top;const result=withRecruitReadFrame(()=>updateRecruitCardContents(id));window.SDF_UI_V223?.decorateCards?.();window.SDF_UI_V219?.decoratePlayerCards?.();window.SDF_UI_V223?.decorateCards?.();window.SDF_UI_V219?.decoratePlayerCards?.();window.SDF_UI_V226?.restoreRecruitCards?.();window.SDF_UI_V232?.polishRecruiting?.();window.SDF_UI_V223?.refreshResources?.();const fresh=document.querySelector?.(selector);if(top!=null&&fresh&&window.innerWidth<=760){const delta=fresh.getBoundingClientRect().top-top;if(Math.abs(delta)>1)window.scrollBy?.(0,delta)}return result}
function updateRecruitCardContents(id){const r=findR(id);if(!r)return false;ensureRecruit(r);let changed=false;document.querySelectorAll(`#recruitTable [data-recruit-id="${CSS.escape(String(id))}"]`).forEach(node=>{const t=document.createElement('tbody');t.innerHTML=recruitTableRowHtml(r);const fresh=t.firstElementChild;if(fresh){node.replaceWith(fresh);changed=true}});document.querySelectorAll(`#recruitCardList [data-recruit-id="${CSS.escape(String(id))}"]`).forEach(node=>{const t=document.createElement('div');t.innerHTML=recruitMobileCardHtml(r);const fresh=t.firstElementChild;if(fresh){node.replaceWith(fresh);changed=true}});renderRecruitSummary();return changed}
function renderRecruitingV2(){ensureAllRecruits();return withRecruitReadFrame(renderRecruitingContents)}
function renderRecruitingContents(){
 const recruitTab=$('recruitingTab');if(recruitTab)recruitTab.dataset.recruitingEngine='modern-v6-local-row';
 if(!$('recruitTable'))return;const all=filteredProspects(),pageSize=window.innerWidth<=760?30:75;window.SDF_RECRUIT_UI??={page:1};const pages=Math.max(1,Math.ceil(all.length/pageSize));window.SDF_RECRUIT_UI.page=clamp(window.SDF_RECRUIT_UI.page,1,pages);const rows=all.slice((window.SDF_RECRUIT_UI.page-1)*pageSize,window.SDF_RECRUIT_UI.page*pageSize);
 renderRecruitSummary();
 $('recruitPager').innerHTML=`<div class="pager-info">Showing ${(window.SDF_RECRUIT_UI.page-1)*pageSize+1}-${Math.min(window.SDF_RECRUIT_UI.page*pageSize,all.length)} of ${all.length}</div><div class="pager-actions"><button class="btn neutral" onclick="changeRecruitRacePage(-1)" ${window.SDF_RECRUIT_UI.page<=1?'disabled':''}>Previous</button><span>${window.SDF_RECRUIT_UI.page}/${pages}</span><button class="btn neutral" onclick="changeRecruitRacePage(1)" ${window.SDF_RECRUIT_UI.page>=pages?'disabled':''}>Next</button></div>`;
 $('recruitTable').innerHTML=rows.map(recruitTableRowHtml).join('');
 $('recruitCardList').innerHTML=rows.map(recruitMobileCardHtml).join('')||'<p class="muted">No prospects match these filters.</p>';
}
window.changeRecruitRacePage=delta=>{window.SDF_RECRUIT_UI??={page:1};window.SDF_RECRUIT_UI.page+=delta;renderRecruitingV2();window.scrollTo({top:$('recruitPager').offsetTop-100,behavior:'smooth'})};
window.renderRecruiting=renderRecruitingV2;

window.openRecruit=id=>{
 const r=findR(id);if(!r)return;ensureRecruit(r);const attrs=r.attrs||{},status=statusFor(r),amount=nilOfferAmount(r),nilOffered=state.nilCommitments?.[r.id],rc=race(r),leader=rc.leader,comparison=leader?.id===USER_ID()?rc.second:leader;
 const topSchools=rc.entries.slice(0,8).map(e=>`<div class="top-school-row ${e.id===USER_ID()?'user-school':''}"><span class="top-school-rank">#${e.rank}</span><img src="${logoFor(e.id)}" alt=""><div><b>${e.school.name}</b><small>${e.offered?'Scholarship offered · ':''}Fit ${e.grade}${e.trend?` · ${e.trend>0?'▲':'▼'}${Math.abs(e.trend).toFixed(1)}`:''}</small></div><strong>${Math.round(e.score)}</strong></div>`).join('');
 const comparisons=r.motivations.map(m=>{const your=schoolGrade(r,state.school,m.key),best=comparison?schoolGrade(r,comparison.school,m.key):0;return`<div class="motivation-grade"><div><b>${m.label}</b><small>${importanceLabel(m.weight)} · ${m.weight}% of decision</small></div><span><em>You</em><strong class="grade-${letterGrade(your).charAt(0).toLowerCase()}">${letterGrade(your)}</strong></span><span><em>${leader?.id===USER_ID()?'Next best':'Leader'}</em><strong>${letterGrade(best)}</strong></span></div>`}).join('');
 $('modalBody').innerHTML=`<span class="eyebrow">PROSPECT PROFILE</span><h2>${r.name}</h2><p>${r.pos} · ${r.arch} · <span class="star">${star(r.stars)}</span> · #${r.rank} nationally · ${r.personality}</p><div class="metric-grid">${metric('Hometown',`${r.city}, ${r.home}`)}${metric('Distance',distance(state.school,r)+' mi')}${metric('Your Rank',rc.user?`#${rc.user.rank}`:'Outside top schools')}${metric('Your Interest',Math.round(rc.user?.score||0))}${metric('Interest Limit',status.eligibility.cap>=100?'100/100':`${status.eligibility.cap}/100`)}${metric('Leader',leader?.school.name||'—')}${metric('Gap',rc.user?.rank===1?'Leading':`${Math.round(rc.gap||0)} points`)}${metric('Program Fit',rc.user?.grade||'—')}${metric('Playing Time',letterGrade(playingTimeGrade(r,state.school)))}${metric('Overall',r.scouted?r.ovr:'??')}${metric('Projected Upside',projectedRecruitUpside(r))}${metric('Recruiting Access',status.canRecruit?'Eligible':'Locked')}${metric('Contact Hrs Left',contactHoursLeft(r)+' / '+contactCapFor(r))}${metric('NIL Remaining',formatNilMoney(state.nilBudget))}</div>${!status.canRecruit?`<div class="recruit-lock-message"><b>Active recruiting locked</b><span>${status.activeReason}</span><small>You may still view the race${status.canEvaluate?' and evaluate the prospect':''}.</small></div>`:status.warning?`<div class="recruit-status-message warning"><b>Dealbreaker warning</b><span>${status.warning}</span></div>`:''}<section class="recruit-profile-section"><h3>What Matters to ${r.name.split(' ')[0]}</h3><div class="motivation-row">${motivationChips(r)}</div><div class="motivation-comparison">${comparisons}</div></section><section class="recruit-profile-section"><h3>Top Schools</h3><p class="muted">Interest combines natural school fit, recruiting effort, scholarship offers, visits, promises, and NIL. Other schools recruit every week too.</p><div class="top-schools-list">${topSchools}</div></section>${r.relationship?`<div class="event-card relationship-line"><b>${r.relationship.type}</b><span class="sub">${r.relationship.otherName}</span></div>`:''}${r.scouted?`<section class="recruit-profile-section"><h3>Scouting</h3><div class="metric-grid">${metric('Confidence',(r.scoutConfidence||0)+'%')}${metric('Evaluation',r.evalTag||'On track')}${metric('Overall',r.ovr)}${metric('Projected Upside',projectedRecruitUpside(r))}</div>${window.SDF_V144?.attributeHtml?.(r)||`<div class="metric-grid">${metric('Speed',attrs.speed)}${metric('Strength',attrs.strength)}${metric('Skill',attrs.skill)}${metric('Awareness',attrs.awareness)}</div>`}</section>`:''}<section class="recruit-profile-section"><h3>Recruiting Actions</h3><p class="muted">Available school pool: <b>${state.weeklyHours} hours</b>. Each prospect has a ${contactCapFor(r)}-hour weekly contact cap this week (${contactHoursLeft(r)} left). Recruiter-tree skills can raise the base cap, and matching Head Coach position specialties can raise it further. Each contact action may be used once. All limits reset next week.</p>${r.lastActionMessage?`<div class="action-feedback">${r.lastActionMessage}</div>`:''}<div class="recruit-action-grid">${Object.values(ACTIONS).map(a=>{const p=actionPreview(r,a.key);return`<div class="recruit-action-card"><h4>${a.label} <span>${a.hours} hr${a.hours===1?'':'s'}</span></h4><p>${a.description}</p><small>${p.used?'Already used this week':`${p.weeklySpent}/${p.contactCap} contact hours used · ${p.remaining} left`} · Estimated influence: ${p.estimate.toFixed(1)}</small><button class="btn ${a.key==='HARD_SELL'?'primary':a.key==='FAMILY'?'warning':'neutral'} full" onclick="recruitAction('${r.id}','${a.key}')" ${!canUseAction(r,a.key,status).allowed?'disabled':''}>Use ${a.label}</button></div>`}).join('')}</div></section><section class="recruit-profile-section"><h3>Scholarship, Visit & NIL</h3><div class="actions"><button class="btn neutral" onclick="offer('${r.id}')" ${!status.canRecruit||r.offered||state.scholarships<=0?'disabled':''}>${r.offered?'Scholarship Offered':'Offer Scholarship'}</button>${nilButton(r,status,true)}<button class="btn warning" onclick="visit('${r.id}')" ${!status.canRecruit||state.weeklyHours<20||r.visit?'disabled':''}>${r.visit?'Visit Scheduled':'Schedule Official Visit (20 hrs)'}</button><button class="btn neutral" onclick="openRecruitPromiseMenu('${r.id}')" ${!status.canRecruit?'disabled':''}>Make Promise</button><button class="btn danger" onclick="useNegativeRecruiting('${r.id}')" ${!status.canRecruit||state.weeklyHours<15?'disabled':''}>Negative Recruit Leader (15 hrs)</button></div><div class="nil-detail"><b>NIL request: ${formatNilMoney(amount)}</b><span>${nilOffered?`You offered ${formatNilMoney(nilOffered)} against a ${formatNilMoney(amount)} request — ${nilReaction(nilOffered,amount).label}.`:`You have ${formatNilMoney(state.nilBudget)} remaining. Choose the offer amount yourself.`}</span></div></section>`;
 $('modal').classList.remove('hidden');const card=$('modal').querySelector('.modal-card');if(card)card.scrollTop=0
};

// Kept as a tiny compatibility entry point for older saves and extension modules.
// The separate quick/all-options UI is retired; every call opens the tabbed profile.
window.openRecruitQuickMenu=id=>window.openRecruit(id);
window.setPlan=(id,plan)=>{const r=findR(id);if(!r)return;ensureRecruit(r);if(plan==='NONE'){r.weeklyPlan='NONE';updateRecruitCard(r.id);autosave();return}if(!addToBoard(r))return;const status=statusFor(r);if(!status.canRecruit){r.weeklyPlan='NONE';rejectRecruitAction(r,status.activeReason);return}r.weeklyPlan=PLAN_ACTION_MAP[plan]||plan;updateRecruitCard(r.id);autosave('Weekly recruiting plan')};
window.offer=id=>{const r=findR(id);if(!r)return;ensureRecruit(r);const status=statusFor(r);if(!status.canRecruit){rejectRecruitAction(r,status.activeReason);return}if(r.offered||state.scholarships<=0||!addToBoard(r))return;r.offered=true;state.scholarships--;recalculateRecruit(r,true);maybeImmediateCommit(r);state.news.push(`${r.name} received a scholarship offer from ${state.school.name}.`);updateRecruitCard(r.id);autosave('Scholarship offer')};
function updateNilOfferPreview(id){const r=findR(id),input=$('nilOfferInput'),out=$('nilOfferPreview');if(!r||!input||!out)return;const amount=Math.max(0,Number(input.value||0)),ask=nilOfferAmount(r),reaction=nilReaction(amount,ask),diff=amount-ask;out.className=`nil-offer-reaction ${reaction.tone}`;out.innerHTML=`<b>${reaction.label}</b><span>${formatNilMoney(amount)} offer · ${diff===0?'matches the request':diff>0?`${formatNilMoney(diff)} above the request`:`${formatNilMoney(Math.abs(diff))} below the request`} · Interest effect ${reaction.bonus>=0?'+':''}${reaction.bonus}</span>`}
window.setNilOfferPreset=(id,amount)=>{const input=$('nilOfferInput'),number=$('nilOfferNumber');if(!input)return;const value=Math.max(0,Math.round(Number(amount||0)/1000)*1000);input.value=value;if(number)number.value=value;updateNilOfferPreview(id)};
window.submitNilOffer=id=>{const r=findR(id);if(!r)return;ensureRecruit(r);const status=statusFor(r),ask=nilOfferAmount(r),current=Number(state.nilCommitments?.[r.id]||0),input=$('nilOfferInput'),amount=Math.max(0,Math.round(Number(input?.value||0)/1000)*1000),available=Number(state.nilBudget||0)+current;if(!status.canRecruit){rejectRecruitAction(r,status.activeReason);return}if(!addToBoard(r))return;if(amount>available){rejectRecruitAction(r,`not enough NIL money — ${formatNilMoney(available)} is available including your current offer`);return}state.nilCommitments??={};state.nilBudget=available-amount;if(amount)state.nilCommitments[r.id]=amount;else delete state.nilCommitments[r.id];const reaction=nilReaction(amount,ask);if(reaction.bonus<0)r.nilTrustPenalty=clamp(Number(r.nilTrustPenalty||0)+Math.abs(reaction.bonus)*.25,0,4);else if(reaction.bonus>=9)r.nilTrustPenalty=Math.max(0,Number(r.nilTrustPenalty||0)-2);r.nilReaction={amount,ask,label:reaction.label,bonus:reaction.bonus,week:state.week,year:state.year};recalculateRecruit(r,true);maybeImmediateCommit(r);state.news.push(`${r.name}: NIL offer set at ${formatNilMoney(amount)} against a ${formatNilMoney(ask)} request — ${reaction.label}.`);$('modal').classList.add('hidden');updateRecruitCard(r.id);autosave('NIL negotiation')};
window.offerNil=id=>{const r=findR(id);if(!r)return;ensureRecruit(r);const status=statusFor(r),ask=nilOfferAmount(r),current=Number(state.nilCommitments?.[r.id]||0),available=Number(state.nilBudget||0)+current;if(!status.canRecruit){rejectRecruitAction(r,status.activeReason);return}const max=Math.max(ask*2,available),defaultOffer=current||ask,presets=[Math.round(ask*.67/1000)*1000,Math.round(ask/1000)*1000,Math.round(ask*1.33/1000)*1000];$('modalBody').innerHTML=`<span class="eyebrow">NIL NEGOTIATION</span><h2>${r.name}</h2><p class="muted">Choose the actual NIL offer. Meeting or beating the request helps; a lowball can reduce interest.</p><div class="metric-grid">${metric('Requested',formatNilMoney(ask))}${metric('Current Offer',current?formatNilMoney(current):'None')}${metric('Available Pool',formatNilMoney(available))}${metric('Priority',r.motivations?.find(m=>m.key==='NIL')?.label||r.priority)}</div><div class="nil-preset-row"><button class="btn danger" onclick="setNilOfferPreset('${r.id}',${presets[0]})">Lowball ${formatNilMoney(presets[0])}</button><button class="btn neutral" onclick="setNilOfferPreset('${r.id}',${presets[1]})">Meet Ask ${formatNilMoney(presets[1])}</button><button class="btn success" onclick="setNilOfferPreset('${r.id}',${presets[2]})">Beat Ask ${formatNilMoney(presets[2])}</button></div><label class="nil-offer-control"><span>Custom NIL offer</span><input id="nilOfferInput" type="range" min="0" max="${Math.max(1000,Math.min(max,available))}" step="1000" value="${Math.min(defaultOffer,available)}" oninput="updateNilOfferPreview('${r.id}')"><input id="nilOfferNumber" class="nil-number-input" type="number" min="0" max="${available}" step="1000" value="${Math.min(defaultOffer,available)}" onchange="document.getElementById('nilOfferInput').value=this.value;updateNilOfferPreview('${r.id}')" oninput="document.getElementById('nilOfferInput').value=this.value;updateNilOfferPreview('${r.id}')"></label><div id="nilOfferPreview" class="nil-offer-reaction"></div><div class="actions"><button class="btn primary" onclick="submitNilOffer('${r.id}')">Submit NIL Offer</button>${current?`<button class="btn danger" onclick="setNilOfferPreset('${r.id}',0);submitNilOffer('${r.id}')">Withdraw NIL Offer</button>`:''}<button class="btn neutral" onclick="openRecruit('${r.id}')">Back to Profile</button></div>`;$('modal').classList.remove('hidden');updateNilOfferPreview(r.id);const card=$('modal').querySelector('.modal-card');if(card)card.scrollTop=0};
window.updateNilOfferPreview=updateNilOfferPreview;
window.visit=id=>{const r=findR(id);if(!r)return;ensureRecruit(r);const status=statusFor(r);if(!status.canRecruit){rejectRecruitAction(r,status.activeReason);return}if(state.weeklyHours<20||r.visit||!addToBoard(r))return;state.weeklyHours-=20;r.visit=true;state.news.push(`${r.name} scheduled an official visit.`);$('modal').classList.add('hidden');updateRecruitCard(r.id);autosave('Official visit')};
