function aiSchemeFor(s){
 if(!s)return{offense:'Pro Style',defense:'Multiple'};
 const exact=REAL_LIFE_SCHEMES[s.name];if(exact)return{offense:exact[0],defense:exact[1]};
 const offenses=['Pro Style','Spread','Air Raid','Power Run','Option','Tempo Spread','RPO Spread','Veer & Shoot','West Coast','Pistol'];
 const defenses=['4-3','3-4','4-2-5','3-3-5','Multiple','Tite / Mint','2-4-5 Nickel','3-2-6 Dime','4-4','Bear / 46'];
 let oi=hash13(`${s.name}-off-v212`)%offenses.length,di=hash13(`${s.name}-def-v212`)%defenses.length;
 if(Number(s.prestige)>=85&&oi===4)oi=6;
 return{offense:offenses[oi],defense:defenses[di]};
}
