function withdrawOffer(id){const r=findR(id);if(!r||!r.offered||r.committedTo)return;const penalty=state.week>=9?9:state.week>=6?6:3,hasPromise=(state.promises||[]).some(p=>p.targetId===r.id&&!p.resolved),nil=Number(state.nilCommitments?.[r.id]||0),message=`Withdraw the scholarship from ${r.name}? You will recover the scholarship slot, but lose ${penalty}${hasPromise?' plus a broken-promise penalty':''} influence.${nil?` The NIL pledge is cancelled and 90% (${formatNilMoney(Math.round(nil*.9))}) returns to the collective.`:''}`;if(!confirm(message))return;r.offered=false;state.scholarships=Math.min(35,Number(state.scholarships||0)+1);r.weeklyPlan='NONE';r.offerCooldownUntil=state.week+1;const uid=USER();r.recruitInfluence??={};r.interest??={};r.interestTrend??={};r.recruitInfluence[uid]=Math.max(0,Number(r.recruitInfluence[uid]||0)-penalty-(hasPromise?3:0));r.interestTrend[uid]=-(penalty+5);r.interest[uid]=Math.max(2,Number(r.interest[uid]||0)-penalty-5-(hasPromise?3:0));if(nil){state.nilBudget+=Math.round(nil*.9);delete state.nilCommitments[r.id]}if(r.visitScheduledWeek){delete state.recruitVisitCalendar[`${state.year}-${r.visitScheduledWeek}-${r.id}`];r.visitScheduledWeek=null}for(const p of state.promises||[]){if(p.targetId===r.id&&!p.resolved){if(window.SDF_V188?.resolvePromise)window.SDF_V188.resolvePromise(p,false,'The scholarship offer was withdrawn before the commitment was honored.');else{p.resolved=true;p.kept=false}}}state.news.push(`${state.school.name} withdrew ${r.name}'s scholarship offer. The relationship took a hit.`);window.SDF_RECRUITING_V2?.updateRecruitCard?.(r.id)||window.renderAll();save13('Scholarship withdrawn')}
