// Keep game controls mounted while scores, the field and play history update.
let mountedLiveGame=null,gameCenterTab='plays',gameCenterReturnFocus=null,gameCenterFeedSignature='';
function compactTeam(id,name){return String(TEAM_BRANDING?.[Number(id)]?.abbr||teamById(id)?.abbr||name||'TEAM').slice(0,5).toUpperCase()}
function gameCenterTeam(game,side){
 const ours=side==='us',id=ours?state.school.id:game.oppId,name=ours?state.school.name:game.opponent;
 const world=(state.world||[]).find(t=>Number(t.id)===Number(id)),rank=(state.rankings||[]).find(t=>Number(t.id)===Number(id))?.rank,record=ours?state.record:world?.record;
 const site=game.neutral?'Neutral':(ours?game.home:!game.home)?'Home':'Away';
 return `<div class="gc-team gc-team-${side} ${!game.complete&&game.possession===side?'has-ball':''}"><div class="gc-team-identity"><img src="${safe(logo(id))}" alt="" width="64" height="64"><div><span class="gc-team-meta">${rank&&rank<=25?'#'+rank+' · ':''}${site}${record?' · '+n(record.w)+'–'+n(record.l):''}</span><b class="gc-team-name">${safe(name)}</b></div></div><strong class="gc-score" aria-label="${safe(name)} ${n(game.score[side])} points">${n(game.score[side])}</strong><span class="gc-possession">${!game.complete&&game.possession===side?'<i aria-hidden="true"></i>Possession':'&nbsp;'}</span></div>`
}
function renderScoreboard(game){
 return `${gameCenterTeam(game,'us')}<div class="gc-clock"><span>${game.complete?'FINAL':game.quarter<=4?'Q'+game.quarter:'OT '+(game.quarter-4)}</span><strong>${game.complete?'—':game.quarter<=4?clockText(game.clock):'OT'}</strong><small>${game.complete?'Game complete':game.simulatingToFinal?'Finishing game':game.paused?'Paused':'In progress'}</small></div>${gameCenterTeam(game,'them')}`
}
function renderField(game){
 const midfieldLogo=game.neutral?'icon-192.png':logo(game.home?state.school.id:game.oppId);
 const pos=pct(game.ball),first=pct(game.ball+direction(game)*game.distance),yards=[10,20,30,40,50,40,30,20,10];
 const own=compactTeam(state.school.id,state.school.name),opp=compactTeam(game.oppId,game.opponent),offense=game.possession==='us'?own:opp;
 const spot=Math.round(game.ball)===50?'MIDFIELD':`${Math.round(game.ball)<50?own:opp} ${Math.min(Math.round(game.ball),100-Math.round(game.ball))}`,distance=toGoal(game)<=game.distance?'Goal':Math.max(1,Math.round(game.distance));
 return `<div class="gc-field-card"><div class="gc-situation"><div><small>DOWN & DISTANCE</small><b>${ordinal(game.down)} & ${distance}</b></div><div><small>BALL ON</small><b>${safe(spot)}</b></div><div class="gc-drive-direction"><small>ON OFFENSE</small><b>${safe(offense)} <span aria-label="driving ${game.possession==='us'?'right':'left'}">${game.possession==='us'?'→':'←'}</span></b></div></div><div class="gc-field" role="img" aria-label="${safe(possessionTeam(game))} possession. ${safe(situation(game))}. Driving ${game.possession==='us'?'right':'left'}."><div class="gc-endzone gc-endzone-us">${safe(own)}</div><div class="gc-endzone gc-endzone-them">${safe(opp)}</div><div class="gc-playing-area"><div class="gc-yard-numbers">${yards.map((yard,index)=>`<span style="left:${10+index*10}%">${yard}</span>`).join('')}</div><div class="gc-yard-numbers gc-yard-bottom">${yards.map((yard,index)=>`<span style="left:${10+index*10}%">${yard}</span>`).join('')}</div><div class="gc-hash gc-hash-top"></div><div class="gc-hash gc-hash-bottom"></div><img class="gc-midfield-logo" src="${safe(midfieldLogo)}" alt=""><div class="gc-first-down" style="left:${first}%"></div><div class="gc-scrimmage" style="left:${pos}%"></div><div class="gc-football ${game.possession==='them'?'drives-left':''}" style="left:${pos}%"><i></i><span>${game.possession==='us'?'→':'←'}</span></div></div></div><div class="gc-field-key"><span><i class="gc-key-ball"></i>Ball position</span><span><i class="gc-key-first"></i>First down</span></div></div>`
}
function renderTeamStats(game){
 const a=game.stats.us,b=game.stats.them,rows=[['Total yards',a.totalYds,b.totalYds],['Passing yards',a.passYds,b.passYds],['Rushing yards',a.rushYds,b.rushYds],['First downs',a.firstDowns,b.firstDowns],['Turnovers',a.turnovers,b.turnovers],['3rd down',`${a.thirdConv}/${a.thirdAtt}`,`${b.thirdConv}/${b.thirdAtt}`],['4th down',`${a.fourthConv}/${a.fourthAtt}`,`${b.fourthConv}/${b.fourthAtt}`],['Penalties / yards',`${a.penalties} / ${a.penaltyYds}`,`${b.penalties} / ${b.penaltyYds}`],['Possession',clockText(a.timePossession),clockText(b.timePossession)]];
 return `<table class="gc-stats-table" aria-label="Team statistics"><thead><tr><th scope="col"><img src="${safe(logo(state.school.id))}" alt=""><span>${safe(state.school.name)}</span></th><th scope="col"><span class="gc-sr-only">Statistic</span></th><th scope="col"><img src="${safe(logo(game.oppId))}" alt=""><span>${safe(game.opponent)}</span></th></tr></thead><tbody>${rows.map((r,i)=>`<tr ${i===0?'class="gc-stat-total"':''}><td>${r[1]}</td><th scope="row">${r[0]}</th><td>${r[2]}</td></tr>`).join('')}</tbody></table>`
}
function renderPlayerStats(game){
 const top=topPlayers(game);return `<div class="gc-players">${top.length?top.map((s,i)=>`<article><span class="gc-player-position">${safe(s.pos)}</span><div><b>${safe(s.name)}</b><span>${safe(playerLine(s))}</span></div>${i===0?'<small>LEADER</small>':''}</article>`).join(''):'<div class="gc-empty"><b>The opening drive is coming up.</b><span>Your player stats will appear as the game unfolds.</span></div>'}</div>`
}
function renderGameInjuries(game){return game.injuries.length?`<aside class="gc-injuries"><h3>Injury report</h3>${game.injuries.map(i=>`<div><b>${safe(i.player)}</b><span>${safe(i.type)} · ${i.weeks} week${i.weeks===1?'':'s'}</span></div>`).join('')}</aside>`:''}
function setGameCenterTab(tab,moveFocus=false){
 gameCenterTab=['plays','stats','players'].includes(tab)?tab:'plays';const body=$12('gameSimBody');
 body.querySelectorAll('[data-gc-tab]').forEach(button=>{const selected=button.dataset.gcTab===gameCenterTab;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1;if(selected&&moveFocus)button.focus()});
 body.querySelectorAll('[data-gc-panel]').forEach(panel=>panel.hidden=panel.dataset.gcPanel!==gameCenterTab);
 if(gameCenterTab==='plays'&&state.liveGame)renderFeed(state.liveGame)
}
function mountGameCenter(game,body){
 mountedLiveGame=game;gameCenterTab='plays';renderedFeedLength=0;gameCenterFeedSignature='';
 body.innerHTML=`<div class="live-center gc-center"><header class="gc-header"><div><span class="gc-eyebrow">SATURDAY DYNASTY</span><h2 id="gameSimTitle" tabindex="-1">Game Center</h2></div><div class="gc-header-actions"><button type="button" class="gc-button gc-help" id="gcHelpBtn" aria-label="Game Center help">?</button><button type="button" class="gc-button gc-exit" id="liveExitBtn">Save & exit <span aria-hidden="true">↗</span></button></div></header><div class="gc-match-meta"><span>Year ${game.year} · ${safe(game.gameLabel||'Week '+game.week)}</span><span>${game.neutral?'Neutral site':game.home?'Home game':'Away game'} · ${safe(game.weather||'Clear')}</span></div><section class="gc-scoreboard" id="gcScoreboard" aria-label="Scoreboard"></section><div class="gc-presentation"><div id="gcField"></div><section class="gc-latest" id="gcLastPlay" aria-label="Latest play"></section></div><div class="gc-control-dock"><div class="gc-playback"><button type="button" class="gc-button gc-button-primary" id="livePauseBtn">Pause</button><div class="gc-speeds" role="group" aria-label="Simulation speed">${[.5,1,2,4].map(v=>`<button type="button" class="gc-speed" data-speed="${v}" aria-label="${v} times speed">${v===.5?'½':v}×</button>`).join('')}</div></div><button type="button" class="gc-button gc-finish" id="liveFinalBtn">Sim to final <span aria-hidden="true">»</span></button></div><section class="gc-details"><div class="gc-tabs" role="tablist" aria-label="Game details"><button type="button" id="gcTabPlays" data-gc-tab="plays" role="tab" aria-controls="gcPanelPlays">Play by play</button><button type="button" id="gcTabStats" data-gc-tab="stats" role="tab" aria-controls="gcPanelStats">Team stats</button><button type="button" id="gcTabPlayers" data-gc-tab="players" role="tab" aria-controls="gcPanelPlayers">Your players</button></div><section id="gcPanelPlays" data-gc-panel="plays" role="tabpanel" aria-labelledby="gcTabPlays" tabindex="0"><div class="gc-panel-heading"><span id="gcPlayCount">Opening kickoff</span><button type="button" class="gc-latest-button" id="gcLatestBtn" hidden>Jump to latest ↑</button><small>Newest first</small></div><div class="gc-feed" id="gcFeed" tabindex="0" aria-label="Play by play, newest first"></div></section><section id="gcPanelStats" data-gc-panel="stats" role="tabpanel" aria-labelledby="gcTabStats" tabindex="0" hidden><div id="gcTeamStats"></div></section><section id="gcPanelPlayers" data-gc-panel="players" role="tabpanel" aria-labelledby="gcTabPlayers" tabindex="0" hidden><div id="gcPlayerStats"></div></section></section><p class="gc-sr-only" id="gcAnnouncement" role="status" aria-live="polite"></p></div>`;
 $12('livePauseBtn').onclick=()=>{if(game.simulatingToFinal)return;game.paused=!game.paused;game.paused?stopTimer():startTimer();renderGameCenter();$12('gcAnnouncement').textContent=game.paused?'Game paused.':'Game resumed.'};
 $12('liveFinalBtn').onclick=()=>simToFinal();$12('liveExitBtn').onclick=()=>exitGameCenter();
 $12('gcHelpBtn').onclick=()=>{game.paused=true;stopTimer();renderGameCenter();window.SDF_HELP?.openTab?.('livegame')};
 body.querySelectorAll('[data-speed]').forEach(button=>button.onclick=()=>{setLiveSpeed(Number(button.dataset.speed));$12('gcAnnouncement').textContent=`Simulation speed ${button.dataset.speed} times.`});
 body.querySelectorAll('[data-gc-tab]').forEach(button=>{button.onclick=()=>setGameCenterTab(button.dataset.gcTab);button.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=['plays','stats','players'],at=tabs.indexOf(gameCenterTab),next=e.key==='Home'?0:e.key==='End'?2:(at+(e.key==='ArrowRight'?1:2))%3;setGameCenterTab(tabs[next],true)}});
 $12('gcFeed').onscroll=()=>{$12('gcLatestBtn').hidden=$12('gcFeed').scrollTop<24};
 $12('gcLatestBtn').onclick=()=>{$12('gcFeed').scrollTop=0;$12('gcLatestBtn').hidden=true;$12('gcFeed').focus({preventScroll:true})};
 body.onkeydown=e=>{if(document.querySelector('#sdfContextHelp.open,#sdfHelpCenter.open,#tutorialPanel.sdf-guided-welcome:not(.hidden)'))return;if(e.key==='Escape'&&!game.simulatingToFinal){e.preventDefault();e.stopPropagation();exitGameCenter();return}if(e.key!=='Tab')return;const buttons=[...body.querySelectorAll('button:not(:disabled),[tabindex="0"]')].filter(el=>!el.hidden&&el.getClientRects().length),first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$12('gameSimTitle'))){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}};
 setGameCenterTab('plays');$12('gameSimTitle').focus({preventScroll:true})
}
function renderFeed(game){
 const host=$12('gcFeed'),signature=JSON.stringify(game.feed);if(gameCenterFeedSignature===signature)return;
 const anchored=host.scrollTop>24,anchor=anchored?[...host.children].find(row=>row.offsetTop+row.offsetHeight>host.scrollTop):null,key=anchor?.dataset.feedKey,offset=anchor?anchor.offsetTop-host.scrollTop:0;
 gameCenterFeedSignature=signature;
 host.innerHTML=game.feed.length?game.feed.slice().reverse().map(x=>{const type=['score','turnover','injury','penalty','quarter'].includes(x.type)?x.type:'play',label={score:'Scoring play',turnover:'Turnover',injury:'Injury',penalty:'Penalty',quarter:'Game update'}[type];return `<article class="gc-feed-row gc-event-${type}" data-feed-key="${safe(x.quarter+'|'+x.clock+'|'+x.text+'|'+x.score)}"><div class="gc-feed-time"><b>${x.quarter<=4?'Q'+x.quarter:'OT'+(x.quarter-4)}</b><span>${x.quarter<=4?clockText(x.clock):'—'}</span></div><div>${label?`<small>${label}</small>`:''}<p>${safe(x.text)}</p></div><span class="gc-feed-score" aria-label="${safe(state.school.name)} to ${safe(game.opponent)} score">${safe(x.score)}</span></article>`}).join(''):'<div class="gc-empty"><b>Ready for kickoff.</b><span>Every snap, score and turning point will appear here.</span></div>';
 if(anchored&&key){const replacement=[...host.children].find(row=>row.dataset.feedKey===key);if(replacement)host.scrollTop=replacement.offsetTop-offset}else host.scrollTop=0;
 $12('gcLatestBtn').hidden=host.scrollTop<24;renderedFeedLength=game.feed.length
}
function renderGameCenter(){
 const game=state.liveGame,body=$12('gameSimBody');if(!game||!body)return;if(mountedLiveGame!==game||!$12('gcScoreboard'))mountGameCenter(game,body);
 const update=(id,html)=>{const node=$12(id);if(node&&node.innerHTML!==html)node.innerHTML=html};
 update('gcScoreboard',renderScoreboard(game));update('gcField',renderField(game));
 const event=game.feed.at(-1),type=['score','turnover','injury','penalty'].includes(event?.type)?event.type:'play',label={score:'Scoring play',turnover:'Possession change',injury:'Injury update',penalty:'Flag on the play',play:game.plays?'Latest play':'Opening kickoff'}[type];
 $12('gcLastPlay').className='gc-latest gc-event-'+type;
 update('gcLastPlay',`<div class="gc-latest-kicker"><span class="gc-status-dot ${game.paused?'is-paused':''}" aria-hidden="true"></span>${game.simulatingToFinal?'FINISHING':game.paused?'PAUSED':'LIVE'}<span>${label}</span></div><p>${safe(game.lastPlay)}</p><small>${safe(possessionTeam(game))} possession · Drive ${n(game.driveNo,1)}</small>`);
 const pause=$12('livePauseBtn');pause.textContent=game.paused?'▶ Resume':'Ⅱ Pause';pause.setAttribute('aria-label',game.paused?'Resume game':'Pause game');pause.disabled=!!game.simulatingToFinal;
 const finish=$12('liveFinalBtn');finish.innerHTML=game.simulatingToFinal?'Finishing…':'Sim to final <span aria-hidden="true">»</span>';finish.disabled=!!game.simulatingToFinal;$12('liveExitBtn').disabled=!!game.simulatingToFinal;$12('gcHelpBtn').disabled=!!game.simulatingToFinal;
 body.querySelectorAll('[data-speed]').forEach(button=>{button.setAttribute('aria-pressed',String(Number(button.dataset.speed)===currentSpeed));button.disabled=!!game.simulatingToFinal});
 $12('gcPlayCount').textContent=`${game.plays} plays${game.feed.length>=180?' · Recent history':''}`;if(gameCenterTab==='plays')renderFeed(game);update('gcTeamStats',renderTeamStats(game));update('gcPlayerStats',renderPlayerStats(game)+renderGameInjuries(game))
}

function postseasonFinalCopy(game,win){
 const type=game.contextType||'REGULAR',stage=Number(game.contextMeta?.stage),label=safe(game.gameLabel||'Postseason');
 if(type==='PLAYOFF'&&stage===3)return win?{eyebrow:'NATIONAL CHAMPIONS',title:'🏆 Congratulations — you won the National Championship!',body:`${safe(state.school.name)} finished the job and reached the top of college football.`}:{eyebrow:'NATIONAL RUNNER-UP',title:'So close — the title game got away.',body:`A brutal finish, but ${safe(state.school.name)} made it all the way to the National Championship.`};
 if(type==='BOWL')return win?{eyebrow:'BOWL CHAMPIONS',title:`🏆 ${label} Champions!`,body:`Congratulations — ${safe(state.school.name)} closed the season with a bowl victory.`}:{eyebrow:'BOWL FINAL',title:'Tough ending to the season.',body:`${safe(state.school.name)} came up short in ${label}, but the season is officially in the books.`};
 if(type==='CONFERENCE')return win?{eyebrow:'CONFERENCE CHAMPIONS',title:'🏆 Conference Champions!',body:`${safe(state.school.name)} won the conference and earned its postseason moment.`}:{eyebrow:'CONFERENCE FINAL',title:'Conference title slips away.',body:`${safe(state.school.name)} fell short in the conference championship.`};
 if(type==='PLAYOFF'&&!win)return{eyebrow:'PLAYOFF FINAL',title:'The playoff run ends here.',body:`${safe(state.school.name)} was eliminated in ${label}.`};
 return null
}
function renderFinal(game){
 const body=$12('gameSimBody');if(!body)return;
 mountedLiveGame=null;body.onkeydown=null;
 const win=game.score.us>game.score.them,special=postseasonFinalCopy(game,win);
 body.innerHTML=`<div class="gc-final"><div class="gc-final-heading"><span class="gc-eyebrow">${special?.eyebrow||'THE FINAL WHISTLE'}</span><h2 id="gameSimTitle" tabindex="-1">${special?.title||(win?'Victory.':'Defeat.')}</h2><p>${special?.body||`${safe(game.gameLabel||'Week '+game.week)} · ${win?'Victory':'Defeat'} for ${safe(state.school.name)}`}</p></div><section class="gc-scoreboard" aria-label="Final score">${renderScoreboard(game)}</section><div class="gc-final-grid"><section><h3>Final team stats</h3>${renderTeamStats(game)}</section><section><h3>Your top performers</h3>${renderPlayerStats(game)}</section></div>${renderGameInjuries(game)}<div class="gc-final-actions"><button type="button" id="liveContinueBtn" class="gc-button gc-button-primary">${game.contextType==='REGULAR'?'Continue Dynasty':'Continue Postseason'} <span aria-hidden="true">→</span></button><button type="button" id="liveInjuryBtn" class="gc-button">Open Injury Report</button></div></div>`;
 $12('liveContinueBtn').onclick=()=>{$12('gameSimModal').classList.add('hidden');if(state.postseasonFlow?.pendingAdvance&&window.SDF_V16?.continuePostseasonFlow){window.SDF_V16.continuePostseasonFlow();return}window.showTab('dashboard')};
 $12('liveInjuryBtn').onclick=()=>{$12('gameSimModal').classList.add('hidden');window.showTab('roster');setTimeout(()=>{document.querySelector('#rosterTab .tab-section-btn[data-key="injuries"]')?.click()},60)};
 body.onkeydown=e=>{if(document.querySelector('#sdfContextHelp.open,#sdfHelpCenter.open,#tutorialPanel.sdf-guided-welcome:not(.hidden)'))return;if(e.key!=='Tab')return;const first=$12('liveContinueBtn'),last=$12('liveInjuryBtn');if(e.shiftKey&&(document.activeElement===first||document.activeElement===$12('gameSimTitle'))){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}};
 $12('gameSimTitle').focus({preventScroll:true});body.closest('.game-sim-card').scrollTop=0;tone(win?'win':'loss')
}

function paintGameCenter(force=false){const gap=currentSpeed>=4?520:currentSpeed>=2?700:0,now=Date.now();if(force||gap===0||now-lastGameCenterPaint>=gap){lastGameCenterPaint=now;renderGameCenter();return true}return false}
function gameTick(){
 const game=state.liveGame;if(!game||game.complete||game.paused){stopTimer();return}simulatePlay(game);if(game.complete){finalizeLiveGame(game);return}paintGameCenter();scheduleTick()
}
function scheduleTick(){stopTimer();if(!state.liveGame||state.liveGame.paused||currentSpeed===0)return;timer=setTimeout(gameTick,SPEEDS[currentSpeed]||900)}
function startTimer(){if(!state.liveGame)return;state.liveGame.paused=false;scheduleTick()}
function stopTimer(){if(timer){clearTimeout(timer);timer=null}}
function setLiveSpeed(v){currentSpeed=[.5,1,2,4].includes(v)?v:1;if(state.liveGame&&!state.liveGame.paused)scheduleTick();paintGameCenter(true)}
function simToFinal(){
 const game=state.liveGame;if(!game||game.finalized||game.simulatingToFinal)return;stopTimer();game.paused=true;game.simulatingToFinal=true;renderGameCenter();let safety=0;
 const finishSafely=()=>{if(game.finalized)return;game.simulatingToFinal=false;if(!game.complete){if(game.score.us===game.score.them)game.score.us+=3;game.complete=true;addFeed(game,'The remaining game clock was completed by the fast-sim safety engine.','quarter')}setTimeout(()=>finalizeLiveGame(game),0)};
 const runBatch=()=>{if(state.liveGame!==game||game.finalized)return;try{let count=0;while(!game.complete&&count++<18&&safety++<500)simulatePlay(game);if(game.complete||safety>=500){finishSafely();return}paintGameCenter();setTimeout(runBatch,0)}catch(error){console.error('Sim to Final recovered from an error',error);game.lastPlay='Fast simulation recovered and completed the game.';finishSafely()}};
 setTimeout(runBatch,0)
}
function exitGameCenter(){if(!state.liveGame)return;$12('gameSimModal').classList.add('hidden');state.liveGame.paused=true;stopTimer();window.SDF_RELEASE_TEST?.saveNow?.('Live game paused',false,false);window.renderAll();if(gameCenterReturnFocus?.isConnected)gameCenterReturnFocus.focus({preventScroll:true})}
window.openLiveGameCenter=()=>{
 ensure12();if(window.SDF_CALENDAR243?.isBye()){window.showTab('gameday');window.SDF_CALENDAR243.render();return}if(state.phase!=='REGULAR'&&!state.liveGameContext){alert('There is no live matchup ready.');return}const g=currentGame();if(!g||g.result){alert('There is no unplayed game this week.');return}if(!state.liveGame||state.liveGame.year!==state.year||state.liveGame.week!==state.week)state.liveGame=newLiveGame();
 if(!$12('gameSimBody').contains(document.activeElement))gameCenterReturnFocus=document.activeElement;
 $12('gameResultModal')?.classList.add('hidden');$12('gameSimModal').classList.remove('hidden');$12('closeGameSim').classList.add('hidden');startTimer();paintGameCenter(true);$12('gameSimTitle')?.focus({preventScroll:true});tone('kickoff');window.SDF_RELEASE_TEST?.saveNow?.('Live game started',false,false)
};
function soundContext(){try{if(!audioCtx12)audioCtx12=new(window.AudioContext||window.webkitAudioContext)();return audioCtx12}catch{return null}}
