 ['watchLiveGameBtn','watchLiveDashboardBtn'].forEach(id=>{const b=$12(id);if(b){b.disabled=!resume&&(!!g.result||state.phase!=='REGULAR');b.textContent=resume?'Resume Live Game':'Watch Game Live'}});
