function seedOf(team){const id=Number(team?.id);const direct=Number(team?.seed);if(Number.isFinite(direct)&&direct>0)return direct;return Number((state.postseasonData?.playoffField||[]).find(t=>Number(t.id)===id)?.seed||99)}
function siteFor(type,pair,meta={}){if(type!=='PLAYOFF')return{home:false,neutral:true};const user=pair.find(t=>Number(t.id)===Number(state.school.id)),opp=pair.find(t=>Number(t.id)!==Number(state.school.id));if(!user||!opp)return{home:false,neutral:true};return{home:seedOf(user)<seedOf(opp),neutral:false}}
function setLive(type,label,pair,meta={}){const opp=pair.find(t=>Number(t.id)!==Number(state.school.id)),site=siteFor(type,pair,meta);state.liveGameContext={type,label,meta:{...meta,pair,neutral:site.neutral,home:site.home},game:{opponent:opp.name,oppId:opp.id,oppPower:opp.rosterPower||Math.round((Number(opp.prestige||70)+Number(opp.recent||70))/2),home:site.home,neutral:site.neutral,conference:false,rivalry:false,weather:'Clear',result:null,score:null}};window.showTab('gameday');setTimeout(()=>window.openLiveGameCenter(),30)}
