function runPlayoffStage(stage,priorWinners=[]){const pairs=pairsFor(stage,priorWinners),results=new Array(pairs.length),userIndex=pairs.findIndex(pair=>pair.some(t=>Number(t.id)===Number(state.school.id)));for(let i=0;i<pairs.length;i++)if(i!==userIndex)results[i]=makeResult(pairs[i],roundNames[stage]);state.postseasonFlow={mode:'PLAYOFF',stage,priorWinners,pairs,results,userIndex,pendingAdvance:false,stageComplete:false};window.renderPostseasonBrackets?.();if(userIndex>=0){const pair=pairs[userIndex],opp=pair.find(t=>Number(t.id)!==Number(state.school.id)),home=siteFor('PLAYOFF',pair,{stage}).home;showBid(`${roundNames[stage]}: #${seedOf(state.school)} ${state.school.name} ${home?'hosts':'travels to'} #${seedOf(opp)} ${opp.name}`);setLive('PLAYOFF',roundNames[stage],pair,{stage,userIndex});return}recordStage(stage,results);state.postseasonFlow.stageComplete=true;state.postseasonFlow.pendingAdvance=true;if(stage===0&&seedOf((state.postseasonData.playoffField||[]).find(t=>Number(t.id)===Number(state.school.id)))<=4){notice('First-Round Bye',`${state.school.name} earned a first-round bye. The opening-round games have been simulated and the scores are shown below.`,'Continue to Quarterfinals');return}continuePostseasonFlow()}
