function completePlayoff(ctx,game){const flow=state.postseasonFlow,idx=ctx.meta.userIndex,result=liveResult(ctx.meta.pair,ctx.label,game);if(!flow||flow.mode!=='PLAYOFF')return;flow.results[idx]=result;if(result.winner.id===state.school.id)state.achievementStats.playoffWins++;recordStage(flow.stage,flow.results);flow.stageComplete=true;flow.pendingAdvance=true;if(flow.stage===3){state.postseasonData.nationalChampion=result.winner;if(result.winner.id===state.school.id){state.achievementStats.nationalTitles++;state.trophies.push({year:state.year,type:'National Championship'})}}}
function startBowlOrPlayoff(){if(state.phase!=='BOWLS')return;if(resumePostseason())return;const d=state.postseasonData,f=d.playoffField||[];d.bowlResults=(d.bowls||[]).filter(b=>![b.a.id,b.b.id].includes(state.school.id)).map(b=>simulateNeutralGame(b.a,b.b,b.name));if(f.some(t=>t.id===state.school.id)){if(schoolTier(state.school).key==='REBUILD')state.achievementStats.rebuildPlayoffs++;runPlayoffStage(0,[]);return}const bowl=(d.bowls||[]).find(b=>[b.a.id,b.b.id].includes(state.school.id));if(bowl){showBid(`${bowl.name}: ${state.school.name} vs ${(bowl.a.id===state.school.id?bowl.b:bowl.a).name}`);setLive('BOWL',bowl.name,[bowl.a,bowl.b],{bowlName:bowl.name});return}simulatePlayoffWithoutUser();finishSeason()}
