function completePostseasonGame(ctx,game){if(!ctx)return;state.postseasonApplied242??={};const key=[state.year,ctx.type,ctx.meta?.stage??'',...(ctx.meta?.pair||[]).map(t=>t.id).sort((a,b)=>a-b)].join(':');if(state.postseasonApplied242[key])return;state.postseasonApplied242[key]=true;if(ctx.type==='CONFERENCE')completeConference(ctx,game);if(ctx.type==='BOWL')completeBowl(ctx,game);if(ctx.type==='PLAYOFF')completePlayoff(ctx,game)}
function awardValue(p){const s=p.seasonStats||{};return(s.passYds||0)/20+(s.passTD||0)*7-(s.passINT||0)*4+(s.rushYds||0)/12+(s.rushTD||0)*7+(s.recYds||0)/12+(s.recTD||0)*7+(s.tackles||0)+(s.tfl||0)*2+(s.sacks||0)*5+(s.defINT||0)*7+(s.points||0)/3+(s.inside20||0)*2+p.ovr/3}
function allAwards(){const existing=[...(state.awardsWeek?.awards||[])];if(existing.some(a=>a.teamId!=null)||state.awardsWeek?.nationalAwardsVersion>=181)return existing;const defs=[['Quarterback Award','QB'],['Running Back Award','RB'],['Receiver Award','WR'],['Tight End Award','TE'],['Offensive Line Award',['OT','IOL']],['Defensive Line Award',['EDGE','DL']],['Linebacker Award','LB'],['Defensive Back Award',['CB','S']],['Kicker Award','K'],['Punter Award','P']];defs.forEach(([title,pos])=>{const positions=Array.isArray(pos)?pos:[pos],p=state.roster.filter(x=>positions.includes(x.pos)).sort((a,b)=>awardValue(b)-awardValue(a))[0];if(p&&!existing.some(x=>x.title===title))existing.push({title,player:p.name,pos:p.pos,detail:playerStatLine(p)})});return existing}
function renderAwards(){const panel=$16('awardsWeekPanel');if(!panel)return;const active=state.phase==='AWARDS';panel.classList.toggle('hidden',!active);if(!active)return;const firstView=!state.awardsWeek?.presented,awards=allAwards(),aa=state.awardsWeek?.allAmericans||[],national=awards.some(a=>a.teamId!=null);$16('awardsWeekSummary').innerHTML=metric(national?'National Awards':'Team Awards',awards.length)+metric('Your All-Americans',aa.length)+metric('Final Record',`${state.record.w}-${state.record.l}`)+metric('Trophies',state.trophies.filter(t=>t.year===state.year).length);$16('awardsWeekGrid').innerHTML=`<div class="award-week-section"><h3>${national?'National Award Winners':'Major Awards'}</h3><div class="award-week-cards">${awards.map(a=>`<article><span class="eyebrow">${a.title}</span><h3>${a.player}</h3><span>${a.pos||''}${a.team?` · ${a.team}`:''}</span><small>${a.subtitle?`${a.subtitle} · `:''}${a.detail||''}</small></article>`).join('')}</div></div><div class="award-week-section"><h3>Your All-American Selections</h3><div class="award-week-cards">${aa.map(a=>`<article><span class="eyebrow">ALL-AMERICAN</span><h3>${a.player}</h3><span>${a.pos} · ${a.ovr} OVR</span></article>`).join('')||'<p class="muted">No players from your program earned an All-American selection this season.</p>'}</div></div>`;if(state.awardsWeek)state.awardsWeek.presented=true;const btn=$16('continueAwardsBtn');if(btn)btn.textContent='Enter Offseason';window.showTab('postseason');if(firstView)setTimeout(()=>panel.scrollIntoView?.({behavior:'smooth',block:'start'}),80)}
