// Snap distribution edits stay in a draft until saved. Changing one player
// automatically redistributes the remaining active shares to an exact 100%.
const snapDrafts={};
function roleRating163(role){const slots=state.realDepthChart?.[role.key]?.slots||[],shares=snapDrafts[role.key]||slots.map(s=>num(s.snapShare));let weighted=0,total=0;for(let i=0;i<slots.length;i++){const p=state.roster.find(x=>x.id===slots[i].playerId);if(p&&!p.injury&&!p.redshirt){weighted+=num(p.ovr)*num(shares[i]);total+=num(shares[i])}}return total?Math.round(weighted/total):45}
function snapValues(role){const slots=state.realDepthChart?.[role]?.slots||[];return(snapDrafts[role]||slots.map(s=>num(s.snapShare))).slice()}
function ensureSnapDraft(role){if(!snapDrafts[role])snapDrafts[role]=snapValues(role);return snapDrafts[role]}
window.setRealDepthPlayer=function(role,index,id){window.SDF_V11_TEST?.ensureRealDepth?.();const defs=window.SDF_V11_TEST?.ROLE_DEFS||[],def=defs.find(r=>r.key===role),slots=state.realDepthChart?.[role]?.slots;if(!def||!slots?.[index])return;if(id){defs.filter(r=>r.pos===def.pos).forEach(r=>(state.realDepthChart?.[r.key]?.slots||[]).forEach((slot,i)=>{if(!(r.key===role&&i===index)&&slot.playerId===id)slot.playerId=''}))}slots[index].playerId=id;window.SDF_V11_TEST?.ensureRealDepth?.();window.renderDepthManager?.();saveNow('Depth chart updated')};
function rebalanceSnapDraft(role,index,value){const slots=state.realDepthChart?.[role]?.slots||[],draft=ensureSnapDraft(role);if(index<0||index>=draft.length)return;const next=clamp(Math.round(num(value)),0,100),others=draft.map((v,i)=>({i,value:Math.max(0,num(v)),active:!!slots[i]?.playerId})).filter(x=>x.i!==index),eligible=others.filter(x=>x.active);draft[index]=next;if(!eligible.length){others.forEach(x=>draft[x.i]=0);return}const remaining=100-next,weight=eligible.reduce((n,x)=>n+x.value,0);let used=0;eligible.forEach((x,i)=>{const share=i===eligible.length-1?remaining-used:Math.round(remaining*(weight?x.value/weight:1/eligible.length));draft[x.i]=clamp(share,0,remaining-used);used+=draft[x.i]});others.filter(x=>!x.active).forEach(x=>draft[x.i]=0)}
window.setRealSnapShare=function(role,index,value){window.SDF_V11_TEST?.ensureRealDepth?.();rebalanceSnapDraft(role,index,value);window.renderDepthManager?.()};
window.adjustRealSnapShare=function(role,index,delta){const draft=ensureSnapDraft(role);if(index<0||index>=draft.length)return;rebalanceSnapDraft(role,index,num(draft[index])+num(delta));window.renderDepthManager?.()};
window.autoBalanceRole=function(role){const slots=state.realDepthChart?.[role]?.slots||[],draft=ensureSnapDraft(role),active=slots.map((s,i)=>({s,i})).filter(x=>x.s.playerId);draft.fill(0);active.forEach((x,i)=>draft[x.i]=active.length===1?100:i===active.length-1?Math.max(0,100-draft.reduce((n,v)=>n+num(v),0)):i===0?70:25);window.renderDepthManager?.()};
window.cancelRoleDistribution=function(role){delete snapDrafts[role];window.renderDepthManager?.()};
window.saveRoleDistribution=function(role){const slots=state.realDepthChart?.[role]?.slots||[],shares=snapValues(role),total=shares.reduce((n,v)=>n+num(v),0),ids=slots.map(s=>s.playerId).filter(Boolean);if(total!==100){alert(`Snap shares must total exactly 100%. Current total: ${total}%.`);return}if(new Set(ids).size!==ids.length){alert('The same player cannot fill more than one role in this position group.');return}slots.forEach((s,i)=>s.snapShare=num(shares[i]));delete snapDrafts[role];saveNow('Snap distribution saved',true,false);window.renderDepthManager?.()};
function depthPromiseFlag163(player,snap,starter){if(!player)return'';const promises=window.SDF_V188?.depthPromiseInfo?.(player.id,{snap,starter})||[];if(!promises.length)return'';return`<div class="depth-promise-flags">${promises.map(info=>`<span class="depth-promise-flag ${info.onTrack?'on-track':'at-risk'}" title="${esc(info.criterion)}">⚑ ${esc(info.type)} · ${info.onTrack?'ON TRACK':'AT RISK'}</span>`).join('')}</div>`}
