function renderTeamForm(){const s=current(),host=$p('#sdfTeamForm');if(!s||!host)return;const tmp=document.createElement('div');tmp.innerHTML=teamFormHtml(s,activeTeamId);host.replaceWith(tmp.firstElementChild);pendingTeamLogo=null;$p('#teLogo').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{pendingTeamLogo=await window.SDF_V195?.readLogoFile?.(f);if(pendingTeamLogo)$p('#teLogoPreview').src=pendingTeamLogo}catch(err){editorToast(err?.message||'Could not load logo.',true)}};$p('#teResetLogo').onclick=()=>{pendingTeamLogo='__RESET__';const base=window.SDF_V195?.defaultLogo?.(activeTeamId)||'icon-192.png';$p('#teLogoPreview').src=base};$p('#teSave').onclick=saveTeam;lockPreviewControls()}
function saveTeam(){const s=current();if(!s?.school||!activeTeamId)return;const api=window.SDF_V195;if(!api?.applyTeamEdit)return editorToast('Build 195 Team Editor runtime is unavailable.',true);const changes={name:$p('#teName').value,abbr:$p('#teAbbr').value,conference:$p('#teConference').value,city:$p('#teCity').value,state:$p('#teState').value,primary:$p('#tePrimary').value,secondary:$p('#teSecondary').value,accent:$p('#teAccent').value,prestige:$p('#tePrestige').value,recent:$p('#teRecent').value,facilities:$p('#teFacilities').value,pro:$p('#tePro').value,nil:$p('#teNil').value,academics:$p('#teAcademics').value,stadiumName:$p('#teStadium').value,stadiumCapacity:$p('#teCapacity').value};if(pendingTeamLogo)changes.logoData=pendingTeamLogo;api.applyTeamEdit(s,activeTeamId,changes);const team=api.resolvedTeam(s,activeTeamId),id=activeTeamId,name=team.name;if(commit(`League Team Editor: ${name}`)){openTeamEditor(id,true);setTimeout(()=>editorToast(`${name} saved.`),0)}}
function openTeamEditor(id=null,skip=false){if(typeof id==='boolean'){skip=id;id=null}if(!skip&&!requireOwned('team_editor'))return;const s=begin();if(!s?.school){work=null;window.toast?.('Load a dynasty before opening Team Editor.','error');return}const teams=leagueTeams(s);activeTeamId=id&&teams.some(t=>Number(t.id)===Number(id))?Number(id):Number(s.school.id);showEditor('League Team Editor',`${editorPreview?'Read-only preview · ':''}edit identity, branding, conference, ratings and stadium for all 128 programs`,`<div class="sdf-ed-grid"><aside class="sdf-ed-panel"><h3>All Programs</h3><button id="teConferenceManager" class="sdf-editor-filter">${owns('commissioner_mode')||editorPreview?'Conference Manager':'🔒 Conference Manager'}</button><input id="teSearch" class="sdf-ed-search" type="search" placeholder="Search team or conference"><div class="sdf-player-list">${teams.map(t=>`<button class="sdf-player-row ${Number(t.id)===Number(activeTeamId)?'active':''}" data-id="${t.id}" data-q="${esc(`${t.name} ${t.abbr||''} ${t.conference} ${t.city||''} ${t.state||''}`.toLowerCase())}"><span><b>${esc(t.name)}</b><br><small>${esc(t.conference)} · ${esc(t.abbr||'')}</small></span><img src="${esc(t.logo||'icon-192.png')}" alt="" style="width:30px;height:30px;object-fit:contain"></button>`).join('')}</div></aside>${teamFormHtml(s,activeTeamId)}</div>`);$p('#teConferenceManager').onclick=()=>{if(!discardAllowed())return;editorDirty=false;openConferenceManager(true)};$p('#teSearch').oninput=e=>$$p('.sdf-player-row',$p('#sdfAndroidEditor')).forEach(b=>b.hidden=!b.dataset.q.includes(e.target.value.trim().toLowerCase()));$$p('.sdf-player-row',$p('#sdfAndroidEditor')).forEach(b=>b.onclick=()=>{if(!discardAllowed())return;editorDirty=false;activeTeamId=Number(b.dataset.id);$$p('.sdf-player-row',$p('#sdfAndroidEditor')).forEach(x=>x.classList.toggle('active',x===b));renderTeamForm()});renderTeamForm();decoratePreview('team')}

function openConferenceManager(skip=false){if(!editorPreview&&!skip&&!owns('commissioner_mode')){openShop('commissioner_mode');setShopStatus('Conference Manager is included with Commissioner Mode.');return}if(!editorPreview&&skip&&!owns('commissioner_mode')){openShop('commissioner_mode');setShopStatus('Conference Manager is included with Commissioner Mode.');return}const s=begin();if(!s?.school)return;const teams=leagueTeams(s),confs=window.SDF_V195?.conferences?.()||[...new Set(teams.map(t=>t.conference))],eco=s.conferenceEcosystem||{},activity=Number(s.realismSettings?.realignment??1);showEditor('Conference Manager',`${editorPreview?'Read-only preview · ':''}organize every program and control automatic promotion and relegation`,`<section class="sdf-ed-panel"><div class="sdf-form"><label class="wide"><input id="cmAuto" type="checkbox" ${eco.autoRealignment===false?'':'checked'}> AUTOMATIC PROMOTION &amp; RELEGATION</label><label class="wide">REALIGNMENT ACTIVITY<select id="cmActivity"><option value="0.5" ${activity<.75?'selected':''}>Conservative · up to 1 swap</option><option value="1" ${activity>=.75&&activity<1.3?'selected':''}>Normal · up to 2 swaps</option><option value="1.5" ${activity>=1.3?'selected':''}>Active · up to 3 swaps</option></select></label></div><p class="sdf-team-editor-note-v195">Teams qualify from three completed seasons. Sustained winners can move up; sustained struggling programs can move down. Manual assignments below take effect immediately in this dynasty.</p><input id="cmSearch" class="sdf-ed-search" type="search" placeholder="Search team or conference"><div class="sdf-conference-manager">${confs.map(conf=>`<section><h3>${esc(conf)} <small>${teams.filter(t=>t.conference===conf).length} teams</small></h3>${teams.filter(t=>t.conference===conf).map(t=>`<label class="sdf-conference-team" data-q="${esc(`${t.name} ${conf}`.toLowerCase())}"><span>${esc(t.name)}</span><select data-team-id="${t.id}" data-original="${esc(t.conference)}">${confs.map(c=>`<option ${c===t.conference?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`).join('')}</section>`).join('')}</div><div class="sdf-ed-actions"><button id="cmBack" class="sdf-secondary">Back to Team Editor</button><button id="cmSave" class="sdf-save">Save Conference Setup</button></div></section>`);$p('#cmSearch').oninput=e=>$$p('.sdf-conference-team',$p('#sdfAndroidEditor')).forEach(row=>row.hidden=!row.dataset.q.includes(e.target.value.trim().toLowerCase()));$p('#cmBack').onclick=()=>{if(!discardAllowed())return;editorDirty=false;openTeamEditor(null,true)};$p('#cmSave').onclick=()=>saveConferenceManager();decoratePreview('conference')}
function saveConferenceManager(){const s=current(),api=window.SDF_V195;if(!s||!api?.applyTeamEdit)return;let moved=0;for(const select of $$p('[data-team-id]',$p('#sdfAndroidEditor'))){if(select.value===select.dataset.original)continue;api.applyTeamEdit(s,Number(select.dataset.teamId),{conference:select.value});moved++}s.conferenceEcosystem??={};s.conferenceEcosystem.autoRealignment=$p('#cmAuto').checked;s.realismSettings??={};s.realismSettings.realignment=Number($p('#cmActivity').value)||1;if(commit('Commissioner Mode conference setup')){openConferenceManager(true);setTimeout(()=>editorToast(`${moved} team assignment${moved===1?'':'s'} updated. Automatic realignment ${s.conferenceEcosystem.autoRealignment?'enabled':'disabled'}.`),0)}}

function injectProfileEditor(id){profilePlayerId=id;const body=$p('#modalBody');if(!body)return;let wrap=$p('.sdf-profile-editor-wrap',body);if(!wrap){wrap=document.createElement('div');wrap.className='sdf-profile-editor-wrap';const grid=$p('.metric-grid',body);if(grid)grid.before(wrap);else body.prepend(wrap)}let b=$p('#sdfProfilePlayerEditorBtn',wrap);if(!b){b=document.createElement('button');b.id='sdfProfilePlayerEditorBtn';b.type='button';b.className='sdf-paid-tool';b.onclick=()=>openPlayerEditor(profilePlayerId);wrap.append(b)}const ok=owns('player_editor');b.classList.toggle('locked',!ok);b.textContent=ok?'✦ EDIT PLAYER':'🔒 EDIT PLAYER'}
