 const mm=$p('#mobileMoreMenu'),close=$p('#mobileMoreClose');if(mm&&close&&!$p('#sdfMobileShopBtn')){const b=document.createElement('button');b.id='sdfMobileShopBtn';b.type='button';b.textContent='Shop & Upgrades';b.onclick=()=>{mm.classList.add('hidden');openShop()};mm.insertBefore(b,close)}
