function ensure(){if(!state||!state.school)return;state.promiseSystemVersion=BUILD;state.promiseReputationV188=clip(state.promiseReputationV188??70,0,100);state.promiseHistoryV188=Array.isArray(state.promiseHistoryV188)?state.promiseHistoryV188:[];state.playerUsageV188=state.playerUsageV188&&typeof state.playerUsageV188==='object'?state.playerUsageV188:{};state.usageRecordedWeeksV188=Array.isArray(state.usageRecordedWeeksV188)?state.usageRecordedWeeksV188:[];state.promises=Array.isArray(state.promises)?state.promises:[];state.promises.forEach(normalizePromise);for(const p of state.roster||[])p.trust=clip(p.trust??trustDefault(p),0,100);recalculateCulture()}
function recalculateCulture(){if(!state?.school)return 70;const roster=state.roster||[],morale=roster.length?mean(roster.map(p=>p.morale)):70,trust=roster.length?mean(roster.map(p=>p.trust??trustDefault(p))):70,rep=Number(state.promiseReputationV188??70),captains=(state.captains||[]).filter(id=>roster.some(p=>p.id===id)).length,leadership=Number(window.SDF_V192?.cultureLeadershipScore?.()??clip(52+captains*16,45,100)),eventMod=clip(state.cultureEventModifierV188||0,-12,12),culture=clip(Math.round(morale*.32+trust*.34+rep*.24+leadership*.10+eventMod),0,100);state.teamCultureV188=culture;state.cultureComponentsV188={morale:Math.round(morale),trust:Math.round(trust),promises:Math.round(rep),leadership:Math.round(leadership)};return culture}
function cultureLabel(v=state.teamCultureV188){return v>=88?'Elite':v>=78?'Strong':v>=65?'Stable':v>=52?'Fragile':'Unsettled'}
function cultureRecruitingPct(){const c=recalculateCulture();return clip((c-60)*.0015,-.04,.05)}
function cultureMoraleProtection(){const c=recalculateCulture();return c<=70?0:clip((c-70)/180,0,.12)}
function transferRiskMultiplier(p){const c=recalculateCulture(),trust=Number(p?.trust??70),trustMult=clip(1+(62-trust)*.018,.58,1.55),cultureMult=clip(1+(62-c)*.012,.72,1.28),identityMult=Number(window.SDF_V190?.transferRiskMultiplier?.(p)||1),personMult=Number(window.SDF_V192?.transferRiskMultiplier?.(p)||1);return trustMult*cultureMult*identityMult*personMult}
function portalRiskLabel(p){const base=!p.starter&&p.morale<62?1.45:!p.starter&&p.morale<72?1.0:.60,mult=base*transferRiskMultiplier(p);return mult>=1.45?'High':mult>=.88?'Medium':'Low'}
function addHistory(p){state.promiseHistoryV188.unshift({id:p.id,target:p.target,type:p.type,year:p.year,resolvedYear:p.resolvedYear,kept:p.kept,resolution:p.resolution});state.promiseHistoryV188=state.promiseHistoryV188.slice(0,36)}
function resolvePromise(p,kept,reason,{neutral=false}={}){if(!p||p.resolved)return false;normalizePromise(p);p.resolved=true;p.kept=neutral?null:!!kept;p.resolvedYear=state.year;p.resolution=reason||'';p.status=neutral?'CLOSED':kept?'KEPT':'BROKEN';if(!neutral){const player=(state.roster||[]).find(x=>x.id===p.targetId);if(player){const positiveMult=1+Number(window.coachEffect?.('promiseTrustGainPct')||0),trustDelta=kept?Math.round(11*positiveMult):-20,moraleDelta=kept?6:-11;player.trust=clip(Number(player.trust??trustDefault(player))+trustDelta,0,100);player.morale=clip(Number(player.morale||70)+moraleDelta,0,99)}state.promiseReputationV188=clip(Number(state.promiseReputationV188||70)+(kept?4:-9),0,100);state.news??=[];state.news.push(`${kept?'Promise kept':'Promise broken'}: ${p.type} to ${p.target}. ${reason}`)}addHistory(p);window.SDF_V192?.afterPromiseResolution?.(p,kept);recalculateCulture();return true}
function recordCompletedUsage(){if(!state?.school||state.phase==='PORTAL')return;const recorded=new Set(state.usageRecordedWeeksV188||[]);for(const g of state.schedule||[]){if(!g?.result)continue;const key=`${state.year}-${g.week}`;if(recorded.has(key))continue;for(const p of state.roster||[]){const current=assignedUsage(p),u=state.playerUsageV188[p.id]||{year:state.year,games:0,starts:0,snapTotal:0};if(Number(u.year)!==Number(state.year)){u.year=state.year;u.games=0;u.starts=0;u.snapTotal=0}u.games++;u.starts+=current.starter?1:0;u.snapTotal+=current.snap;state.playerUsageV188[p.id]=u;let trustDelta=current.starter?.45:current.snap>=25?.18:current.snap<10&&['Competitive','Ambitious','Volatile'].includes(p.personality)?-.55:-.12;if(['Loyal','Team-first'].includes(p.personality)&&trustDelta<0)trustDelta*=.45;p.trust=clip(Number(p.trust??trustDefault(p))+trustDelta,0,100)}recorded.add(key)}state.usageRecordedWeeksV188=[...recorded].slice(-30)}
function createPromiseRecord(target,type,key,scope){const d=PROMISE_DEFS[key];const rec={id:(window.SDF_SEEDS?.uuid()??crypto.randomUUID()),targetId:target.id,target:target.name,type:d.type,promiseKey:key,scope,year:state.year,createdWeek:state.week,deadlineYear:state.year+(d.deadlineOffset||0),resolved:false,kept:null,status:'ACTIVE'};if(scope==='PLAYER')rec.baselineSnap=usageFor(target.id).avgSnap;state.promises.push(rec);return rec}
function makeRecruitPromise(id,key){ensure();const r=(state.recruits||[]).find(x=>x.id===id),d=PROMISE_DEFS[key];if(!r||!d||d.scope!=='RECRUIT')return false;const active=state.promises.filter(p=>p.targetId===id&&!p.resolved);if(active.some(p=>promiseKey(p)===key)){alert('You already made that promise to this recruit.');return false}if(active.length>=2){alert('You can make at most two active promises to the same recruit.');return false}r.onBoard=true;r.promise=d.type;const created=createPromiseRecord(r,d.type,key,'RECRUIT');return created}
function makePlayerPromise(id,key){ensure();const p=(state.roster||[]).find(x=>x.id===id),d=PROMISE_DEFS[key];if(!p||!d||d.scope!=='PLAYER')return false;const active=state.promises.filter(x=>x.targetId===id&&!x.resolved);if(active.some(x=>promiseKey(x)===key))return false;const rec=createPromiseRecord(p,d.type,key,'PLAYER');p.morale=clip(Number(p.morale||70)+(key==='MORE_PLAYING_TIME'?8:4),0,99);p.trust=clip(Number(p.trust??trustDefault(p))+2,0,100);recalculateCulture();return rec}
function recruitPromiseBoost(r,key){const d=PROMISE_DEFS[key],motivation=key==='EARLY_PLAYING_TIME'||key==='FEATURE_ROLE'||key==='NO_REDSHIRT'?'PLAYING_TIME':'PLAYING_TIME',grade=window.SDF_RECRUITING_V2?.schoolGrade?.(r,state.school,motivation)??70;return clip((2+(grade-55)/12)*(1+Number(window.coachEffect?.('promiseInfluencePct')||0)),1,9)}
