function sideKeyForPlayer(p){return OFFENSE.has(p?.pos)?'oc':DEFENSE.has(p?.pos)?'dc':'head'}
function developmentChance(p){ensure();const key=sideKeyForPlayer(p),coach=coachForKey(key)||coachForKey('head');if(!coach)return Number(window.SDF_V190?.developmentChanceBonus?.(p)||0)+Number(window.SDF_V192?.developmentChanceBonus?.(p)||0);const profile=coach.staffProfileV189;let chance=clip((Number(coach.development||55)-55)*.005,0,.22);if(matchesGroup(profile,p.pos))chance+=profile.positionSpecialty==='ALL'?.025:.10;chance+=(Number(profile.relationship||60)-60)*.001;chance+=Number(window.SDF_V190?.developmentChanceBonus?.(p)||0);chance+=Number(window.SDF_V192?.developmentChanceBonus?.(p)||0);return clip(chance,0,.45)}
function individualFocusBonus(p){return developmentChance(p)>=.20?1:0}
function schemeFit(key){ensure();const c=coachForKey(key),profile=c?.staffProfileV189,current=key==='oc'?state.offense:state.defense;if(!c||!profile)return{grade:'C',bonus:0,current,specialty:'—'};const exact=String(profile.schemeSpecialty)===String(current),rating=Number(c.game||55);let bonus=exact?(rating>=84?2:1):rating>=88?0:-1;bonus=clip(bonus,-1,2);return{grade:exact?(rating>=82?'A':'B+'):rating>=84?'B':'C',bonus,current,specialty:profile.schemeSpecialty,exact}}
function schemeCoordinatorBonus(side){return schemeFit(side==='offense'?'oc':'dc').bonus}
function departureMultiplier(coach){decorateCoach(coach,coach?.role);const p=coach?.staffProfileV189||{};let mult=1+(Number(p.ambition||50)-50)*.012-(Number(p.loyalty||50)-50)*.009-(Number(p.relationship||60)-60)*.006-Math.min(5,Number(p.tenureYears||0))*.025;return clip(mult,.42,1.85)}
function retainCostMultiplier(coach){decorateCoach(coach,coach?.role);const p=coach.staffProfileV189;return clip(1+(p.ambition-55)*.005-(p.loyalty-55)*.003-(p.relationship-60)*.002,.78,1.28)}
function onRetain(coach){decorateCoach(coach,coach?.role);const p=coach.staffProfileV189;p.loyalty=Math.round(clip(p.loyalty+8,0,99));p.relationship=Math.round(clip(p.relationship+7,0,99));return coach}
function advanceStaffYear(){ensure();if(Number(state.staffProfileYearV189)===Number(state.year))return;state.staffProfileYearV189=state.year;const last=state.history?.at?.(-1),wins=Number(last?.wins??state.record?.w??0),expected=Number(state.school?.expectation||6),delta=clip(wins-expected,-4,4);for(const key of ['oc','dc']){const c=coachForKey(key);if(!c)continue;const p=c.staffProfileV189;p.tenureYears=Math.max(1,Number(p.tenureYears||0)+1);p.relationship=Math.round(clip(p.relationship+Math.sign(delta)+(p.loyalty>=75?1:0),25,99));p.loyalty=Math.round(clip(p.loyalty+(delta>=2?1:0),20,99))}}
function regionForPortal(p){const stateCode=String(p?.hometown||'').split(',').pop()?.trim();const match=(typeof LOC!=='undefined'?LOC:[]).find(x=>x[1]===stateCode);return match?.[2]||state.school?.region||'National'}
function portalProxy(p){return{pos:p.pos,region:regionForPortal(p),home:String(p.hometown||'').split(',').pop()?.trim()}}
function staffTraitLine(coach){decorateCoach(coach,coach?.role);const p=coach.staffProfileV189;return`${p.recruitingRegion} recruiter · ${GROUP_LABELS[p.positionSpecialty]} · ${p.schemeSpecialty} scheme · Loyalty ${p.loyalty} · Ambition ${p.ambition}`}
function candidateSpecialtyLabel(coach){decorateCoach(coach,coach?.role);const p=coach.staffProfileV189;return`${p.recruitingRegion} / ${GROUP_LABELS[p.positionSpecialty]} / ${p.schemeSpecialty}`}
