function repCard(label,value,desc){return`<article><small>${esc(label)}</small><b>${value}</b><span>${esc(desc)}</span></article>`}
function renderCoach(){ensurePanels();const host=document.getElementById('coachReputationV194');if(!host)return;const x=calculate(),r=x.reputations;host.innerHTML=`<div class="section-head"><div><span class="eyebrow">COACHING REPUTATION · BUILD 194</span><h2>${esc(x.identityLabel)}</h2><p class="muted">Your career identity is earned from actual results. Schools value different résumés when the coaching carousel opens.</p></div><span class="coach-rep-tier-v194">${tier(r.national)} · ${r.national}</span></div><div class="coach-rep-grid-v194">${repCard('Recruiting',r.recruiting,'Classes, five-stars and recruiting ability')}${repCard('Development',r.developer,'Draft picks, All-Americans and player growth')}${repCard('Game Day',r.gameDay,'Winning, titles, playoffs and rivalry results')}${repCard('Program Builder',r.builder,'Sustained improvement, culture and rebuild results')}${repCard('Career Loyalty',r.loyalty,x.marketLabel)}</div><div class="coach-market-note-v194"><b>Job-market identity: ${esc(x.identityLabel)}</b><span>Elite programs lean toward Game Day + National Reputation. Rebuilds prioritize Program Builder + Development. Talent-starved programs value Recruiting. Career Loyalty can help or hurt cautious administrations.</span></div>`}
function renderCareer(){ensurePanels();const host=document.getElementById('coachLegacyV194');if(!host)return;const x=calculate(),r=x.reputations,story=x.story.slice().reverse().slice(0,12);host.innerHTML=`<div class="coach-career-head-v194"><div><span class="eyebrow">CAREER IDENTITY</span><h3>${esc(x.identityLabel)} · ${tier(r.national)}</h3></div><div><b>${r.national}</b><small>National Reputation</small></div></div><div class="metric-grid compact"><div class="metric"><span>Recruiting Rep</span><b>${r.recruiting}</b></div><div class="metric"><span>Developer Rep</span><b>${r.developer}</b></div><div class="metric"><span>Game-Day Rep</span><b>${r.gameDay}</b></div><div class="metric"><span>Builder Rep</span><b>${r.builder}</b></div><div class="metric"><span>Career Loyalty</span><b>${r.loyalty}</b></div><div class="metric"><span>Current Tenure</span><b>${tenure()} yr</b></div></div><h3>Career Story</h3><div class="coach-story-v194">${story.length?story.map(e=>`<article><b>Year ${e.year}</b><span>${esc(e.text)}</span></article>`).join(''):'<p class="muted">Career milestones will appear as your résumé grows.</p>'}</div>`}
function beforeRender(){calculate();ensurePanels()}
