function readLogoFile(file){return new Promise((resolve,reject)=>{if(!file)return resolve(null);if(file.size>3_000_000)return reject(new Error('Logo file must be under 3 MB.'));const reader=new FileReader();reader.onerror=()=>reject(new Error('Could not read logo file.'));reader.onload=()=>{const url=String(reader.result||'');if(file.type==='image/svg+xml'||url.startsWith('data:image/svg+xml')){if(file.size>250000)return reject(new Error('SVG logos must be under 250 KB.'));return resolve(url);}const img=new Image();img.onerror=()=>reject(new Error('Unsupported logo image.'));img.onload=()=>{const max=256,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);let out;try{out=canvas.toDataURL('image/webp',.88)}catch{out=canvas.toDataURL('image/png')}resolve(out)};img.src=url};reader.readAsDataURL(file)})}

function allTeams(){if(!state.school)return[];const user={id:uid(),name:state.school.name,conference:state.school.conference,prestige:state.school.prestige,recent:state.school.recent,record:{...state.record},rosterPower:typeof teamRatings==='function'?teamRatings().overall:70};return(state.world||[]).filter(t=>Number(t.id)!==uid()).concat(user)}
