function qualityResume(t,provisional){const rank=Object.fromEntries(provisional.map(x=>[Number(x.id),x.provisionalRank])),h=headToHead();let qw=0,bad=0;for(const r of h){if(Number(r.winner)===Number(t.id)){const or=rank[Number(r.loser)]||999;if(or<=25)qw++;}else if(Number(r.loser)===Number(t.id)){const or=rank[Number(r.winner)]||999;if(or>70)bad++}}return{qualityWins:qw,badLosses:bad}}
