function trajectory(id){const rows=(ensure().history[String(id)]||[]).slice(-3);if(rows.length<3)return null;const avgWins=rows.reduce((a,x)=>a+n(x.wins),0)/rows.length,avgConfPct=rows.reduce((a,x)=>{const g=n(x.conferenceWins)+n(x.conferenceLosses);return a+(g?n(x.conferenceWins)/g:.5)},0)/rows.length,top25=rows.filter(x=>n(x.rank,999)<=25).length,tenPlus=rows.filter(x=>n(x.wins)>=10).length,fourOrLess=rows.filter(x=>n(x.wins)<=4).length,avgRank=rows.reduce((a,x)=>a+n(x.rank,80),0)/rows.length,power=rows.reduce((a,x)=>a+n(x.power,70),0)/rows.length;return{rows,avgWins,avgConfPct,top25,tenPlus,fourOrLess,avgRank,power,promotion:avgWins>=8.25&&tenPlus>=1&&top25>=1,demotion:avgWins<=4.75&&fourOrLess>=2&&top25===0,promoteScore:avgWins*8+avgConfPct*22+top25*8+tenPlus*5+power*.18,demoteScore:(12-avgWins)*8+(1-avgConfPct)*18+Math.max(0,75-power)*.18}}
function moveTeam(id,to,type,partnerId=null){id=Number(id);const team=resolvedTeam(state,id),from=team.conference;if(from===to)return false;const w=worldBy(state,id);if(w)w.conference=to;if(id===uid())state.school.conference=to;const baseSchool=schools.find(s=>Number(s.id)===id);if(baseSchool)baseSchool.conference=to;if(state.teamIdentityOverrides?.[String(id)])state.teamIdentityOverrides[String(id)].conference=to;state.conferenceEcosystem.moves.push({year:state.year,teamId:id,teamName:team.name,from,to,type,partnerId});state.conferenceMoveHistory??=[];state.conferenceMoveHistory.push({year:state.year,teamId:id,teamName:team.name,from,to,type});state.news??=[];state.news.push(`${team.name} ${type==='demotion'?'was demoted':'moved'} from ${from} to ${to}.`);return true}
