 id=Number(id);const p=programForTeam(id)||{},champions=state.postseasonData?.champions||[],national=state.postseasonData?.nationalChampion;
 const wonConference=champions.some(x=>Number(x?.id??x)===id),wonTitle=Number(national?.id??national)===id,base=n(baseSchool(id)?.expectation,6);
