  if(d>=4)prestigeDelta+=2;else if(d>=2)prestigeDelta+=1;else if(d<=-4)prestigeDelta-=2;else if(d<=-2)prestigeDelta-=1;
  if(wins>=11)prestigeDelta+=1;else if(wins<=3)prestigeDelta-=1;
