 const room=(roster||[]).filter(x=>x.pos===p.pos&&x.id!==p.id).sort((a,b)=>n(b.ovr)-n(a.ovr));if(!p.starter&&room[0]&&n(room[0].ovr)>=n(p.ovr)+5)risk+=.045;if(n(source?.recent,50)<42)risk+=.035;if(n(p.ovr)>=84&&!p.starter)risk+=.035;
