 const ratings=teamNumbers(),roster=state.roster||[],injured=roster.filter(p=>p.injury).length,redshirts=roster.filter(p=>p.redshirt).length,highRisk=roster.filter(p=>portalRisk(p)==='High').length;
 const metrics=$('rosterCommandRatingsV224');if(metrics)metrics.innerHTML=`<div><small>TEAM</small><b>${ratings.overall}</b><em>OVR</em></div><div><small>OFFENSE</small><b>${ratings.offense}</b><em>OVR</em></div><div><small>DEFENSE</small><b>${ratings.defense}</b><em>OVR</em></div><div><small>ROSTER</small><b>${roster.length}</b><em>PLAYERS</em></div>`;
 const meta=$('rosterCommandMetaV224');if(meta)meta.textContent=`${injured?`${injured} injured · `:'Healthy roster · '}${redshirts} redshirts · ${highRisk} high portal risk · ${Number(state.scholarships||0)} scholarships available`;
 const tab=$('rosterTab'),surfaces=[...(tab?.children||[])].filter(x=>x.matches?.('section.surface')),active=surfaces.findIndex(x=>!x.classList.contains('ui219-panel-hidden')&&!x.classList.contains('hidden'));
