function matchesFilter(p){
 if(rosterFilter==='STARTERS')return roleText(p)==='Starter';
 if(rosterFilter==='INJURED')return!!p.injury;
 if(rosterFilter==='YOUNG')return Number(p.year||1)<=2;
 if(rosterFilter==='RISK')return portalRisk(p)==='High';
 return true;
}
