 const sideDefs=defs.filter(x=>x.side===activeDepthSide),selected=activeDepthRole[activeDepthSide]||'ALL';picker.innerHTML=`<option value="ALL">All ${esc(activeDepthSide)} Positions</option>${sideDefs.map(def=>`<option value="${esc(def.key)}">${esc(def.label)}</option>`).join('')}`;picker.value=sideDefs.some(def=>def.key===selected)?selected:'ALL';activeDepthRole[activeDepthSide]=picker.value;
 const sections=[...host.querySelectorAll(':scope > section.depth-side')];sections.forEach(section=>{const side=section.querySelector(':scope > h3')?.textContent?.trim()||'';section.dataset.depthSide=side;section.hidden=side!==activeDepthSide;const defsForSide=defs.filter(x=>x.side===side),cards=[...section.querySelectorAll('.real-depth-role')];cards.forEach((card,index)=>{const def=defsForSide[index];if(!def)return;card.classList.add('depth-role-v224');card.dataset.depthRole=def.key;card.hidden=side===activeDepthSide&&activeDepthRole[side]!=='ALL'&&activeDepthRole[side]!==def.key;const starter=state.roster?.find(p=>String(p.id)===String(state.realDepthChart?.[def.key]?.slots?.[0]?.playerId));const head=card.querySelector('.depth-position-head');if(head&&!head.querySelector('[data-depth-profile-v224]'))head.insertAdjacentHTML('beforeend',starter?`<button type="button" data-depth-profile-v224 data-player-profile="${esc(starter.id)}"><span>${starter.injury?'OUT':starter.redshirt?'RS':'STARTER'}</span><b>${esc(starter.name)}</b><small>${Number(starter.ovr||0)} OVR · ${Math.round(Number(state.realDepthChart?.[def.key]?.slots?.[0]?.snapShare||0))}% snaps</small></button>`:'<span class="depth-unassigned-v224">Starter unassigned</span>');card.style.setProperty('--room-rating',`${depthRating(def)}%`)})});
 host.querySelectorAll('[data-depth-side]').forEach(button=>button.classList.toggle('active',button.dataset.depthSide===activeDepthSide));
