const num=(value,fallback=0)=>Number.isFinite(Number(value))?Number(value):fallback;
const activePlayerTabs=new Map();

function playerById(id){return(state?.roster||[]).find(player=>String(player.id)===String(id))}
function classText(player){return window.classLabel?.(player)||`Year ${player?.year||1}`}
