function statLine(pos,stats={}){
 const s=new Proxy(stats||{},{get:(target,key)=>num(target[key])});
 if(pos==='QB')return`${s.passComp}/${s.passAtt} passing · ${s.passYds} yds · ${s.passTD} TD · ${s.passINT} INT`;
 if(['RB','FB'].includes(pos))return`${s.rushAtt} carries · ${s.rushYds} yds · ${s.rushTD} TD`;
 if(['WR','TE'].includes(pos))return`${s.rec} catches · ${s.recYds} yds · ${s.recTD} TD`;
 if(['EDGE','DL','LB','CB','S'].includes(pos))return`${s.tackles} tackles · ${s.tfl} TFL · ${s.sacks} sacks · ${s.defINT} INT`;
 if(pos==='K')return`${s.fgm}/${s.fga} FG · ${s.xpm}/${s.xpa} XP · ${s.points} points`;
 if(pos==='P')return`${s.punts} punts · ${s.puntYds} yds · ${s.punts?(s.puntYds/s.punts).toFixed(1):'0.0'} avg · ${s.inside20} inside 20`;
 return`${s.games} games`;
}
function metricCard(label,value,detail=''){return`<div><small>${esc(label)}</small><b>${esc(value)}</b>${detail?`<span>${esc(detail)}</span>`:''}</div>`}
function profileAttributes(player){
 const labels={speed:'Speed',strength:'Strength',skill:'Technique',awareness:'Awareness',acceleration:'Acceleration',agility:'Agility',throwPower:'Throw Power',accuracy:'Accuracy',catching:'Catching',blocking:'Blocking',tackling:'Tackling',coverage:'Coverage',passRush:'Pass Rush',kickPower:'Kick Power',kickAccuracy:'Kick Accuracy'};
 const attrs=player.attrs||{};return Object.entries(attrs).slice(0,8).map(([key,value])=>`<div><span><small>${esc(labels[key]||key.replace(/([A-Z])/g,' $1'))}</small><b>${num(value)}</b></span><i><em style="width:${Math.max(0,Math.min(100,num(value)))}%"></em></i></div>`).join('')||'<p class="muted">Position attributes will appear after evaluation.</p>';
}
function profileProgression(player){
 const rows=(player.progressionHistory||[]).slice(-8).reverse();return rows.map(item=>`<div class="profile-timeline-row-v225"><span>Year ${esc(item.dynastyYear||'—')}</span><div><b>${esc(item.classBefore||'Previous class')} → ${esc(item.classAfter||'Next class')}</b><small>${num(item.from)} → ${num(item.to)} OVR</small></div><strong class="${num(item.gain)>=0?'gain':''}">${num(item.gain)>=0?'+':''}${num(item.gain)}</strong></div>`).join('')||'<p class="muted">The first offseason development result will appear here.</p>';
}
function careerCards(player){
 const history=(player.statHistory||[]).slice(-4),current={year:state.year,team:state.school?.name,ovr:player.ovr,classLabel:classText(player),...(player.seasonStats||{})},seasons=[...history,current];
 return seasons.reverse().map(season=>`<article><div><span>${Number(season.year)===Number(state.year)?'CURRENT SEASON':`DYNASTY YEAR ${esc(season.year)}`}</span><b>${esc(season.classLabel||'Season')} · ${num(season.ovr,player.ovr)} OVR</b></div><strong>${num(season.games)} G</strong><p>${esc(statLine(player.pos,season))}</p></article>`).join('');
}
function activatePlayerTab(shell,key='overview'){
 if(!shell)return;const buttons=[...shell.querySelectorAll('[data-player-tab-v225]')],panels=[...shell.querySelectorAll('[data-player-panel-v225]')];
 if(!buttons.some(button=>button.dataset.playerTabV225===key))key='overview';
 buttons.forEach(button=>{const active=button.dataset.playerTabV225===key;button.classList.toggle('active',active);button.setAttribute('role','tab');button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1});
 panels.forEach(panel=>panel.hidden=panel.dataset.playerPanelV225!==key);
}
