const activeRecruitTabs=new Map();

function recruitById(id){return(state?.recruits||[]).find(recruit=>String(recruit.id)===String(id))}
function buttonLabel(button,recruit){
 const call=button.getAttribute('onclick')||'';
 if(/^toggleBoard\(/.test(call))return recruit.onBoard?'Remove Board':'Add Board';
 if(/^offer\(/.test(call))return recruit.offered?'Offered':'Offer';
 if(/^scout\(/.test(call))return recruit.scouted?'Scouted':'Scout · 8H';
 if(/recruitAction\([^,]+,'TEXT'\)/.test(call))return'Text · 1H';
 if(/recruitAction\([^,]+,'CALL'\)/.test(call))return'Call · 5H';
 if(/recruitAction\([^,]+,'FAMILY'\)/.test(call))return'Family · 10H';
 if(/recruitAction\([^,]+,'HARD_SELL'\)/.test(call))return'Hard Sell · 25H';
 if(/recruitAction\([^,]+,'COACH_VISIT'\)/.test(call))return'Coach Visit · 50H';
 if(/^offerNil\(/.test(call))return Number(state.nilCommitments?.[recruit.id]||0)?'Revise NIL':'NIL Offer';
 if(/^openRecruit\(/.test(call))return'Player Profile';
 return button.textContent.trim();
}
function restoreRecruitCards(){
 for(const card of document.querySelectorAll('#recruitCardList [data-recruit-id]')){
  const recruit=recruitById(card.dataset.recruitId),actions=card.querySelector('.mobile-actions');if(!recruit||!actions)continue;
  const existing=actions.querySelector(':scope > .recruit-card-action-grid-v226');
  if(existing&&actions.children.length===1&&!existing.querySelector('[onclick^="visit("],[onclick^="openRecruitPromiseMenu("],[onclick^="useNegativeRecruiting("]')){card.classList.add('recruit-card-v226');card.dataset.cardRestoredV226='1';continue}
  const profileOnly=/^(visit|openRecruitPromiseMenu|useNegativeRecruiting)\(/;
  const buttons=[...actions.querySelectorAll('button')].filter(button=>!profileOnly.test(button.getAttribute('onclick')||''));
  const plan=actions.querySelector('.plan-select')||card.querySelector(':scope > .plan-select');
  for(const button of buttons){button.textContent=buttonLabel(button,recruit);button.removeAttribute('data-action-kind')}
  actions.querySelectorAll('button').forEach(button=>{if(profileOnly.test(button.getAttribute('onclick')||''))button.remove()});
  const profile=buttons.find(button=>/^openRecruit\(/.test(button.getAttribute('onclick')||''));if(profile){buttons.splice(buttons.indexOf(profile),1);buttons.push(profile);profile.className='btn neutral recruit-card-profile-v226'}
  const grid=document.createElement('div');grid.className='recruit-card-action-grid-v226';
  if(plan){const label=document.createElement('label');label.className='recruit-card-plan-v226';label.innerHTML='<span>Weekly recruiting plan</span>';label.append(plan);grid.append(label)}
  grid.append(...buttons);actions.replaceChildren(grid);actions.className='mobile-actions recruit-actions-restored-v226';card.classList.add('recruit-card-v226');card.dataset.cardRestoredV226='1';
 }
}

