if(typeof baseUpdateRecruitCard==='function')window.updateRecruitCard=function(...args){const result=baseUpdateRecruitCard.apply(this,args);setTimeout(restoreRecruitCards,0);return result};
const baseOpenRecruit=window.openRecruit;
if(typeof baseOpenRecruit==='function')window.openRecruit=function(id,...args){const result=baseOpenRecruit.call(this,id,...args);setTimeout(()=>enhanceRecruitProfile(id),60);return result};
const baseRenderAll=window.renderAll;
