function tablePrimary(headers,cells){
 const priorities=[/^(player|prospect|recruit|name)$/i,/^(team|school|opponent|coach)$/i,/(player|prospect|team|school|opponent|award|event|matchup|record|season)/i];
 for(const pattern of priorities){const index=headers.findIndex((header,i)=>pattern.test(header)&&textOf(cells[i]));if(index>=0)return index}
 const rank=headers.findIndex(header=>/^(#|rank|rk|seed|week|wk)$/i.test(header));
 const index=cells.findIndex((cell,i)=>i!==rank&&textOf(cell));return index>=0?index:0;
}
function tableRank(headers,cells,primary){return headers.findIndex((header,index)=>index!==primary&&/^(#|rank|rk|seed)$/i.test(header)&&textOf(cells[index]))}
function stripDuplicateIds(root){
 const ids=new Map();root.querySelectorAll('[id]').forEach(node=>{const id=`phone-control-v232-${++controlSequence}`;ids.set(node.id,id);node.id=id});
 root.querySelectorAll('[for],[aria-labelledby],[aria-describedby]').forEach(node=>{for(const name of ['for','aria-labelledby','aria-describedby']){const value=node.getAttribute(name);if(value)node.setAttribute(name,value.split(/\s+/).map(id=>ids.get(id)||id).join(' '))}});
}
function syncControl(copy,source){
 if('disabled'in source)copy.disabled=source.disabled;
 if('checked'in source)copy.checked=source.checked;
 if('indeterminate'in source)copy.indeterminate=source.indeterminate;
 if(source.matches('select[multiple]'))[...copy.options].forEach((option,index)=>{option.selected=!!source.options[index]?.selected});
 else if('value'in source&&copy.value!==source.value)copy.value=source.value;
}
function proxyControl(copy,source,key){
 for(const attribute of [...copy.attributes])if(attribute.name.startsWith('on'))copy.removeAttribute(attribute.name);
 controlSources.set(copy,source);syncControl(copy,source);
 // A card's radio group must not uncheck the hidden source radio before its
 // actual event handler runs. Other proxy fields must not duplicate form data.
 if(copy.matches('input[type="radio"]')&&source.name)copy.name=`${key}-${source.name}`;else copy.removeAttribute('name');
 if(!copy.getAttribute('aria-label')&&!copy.getAttribute('aria-labelledby')&&source.labels?.length)copy.setAttribute('aria-label',[...source.labels].map(textOf).join(' '));
 if(copy.matches('button'))copy.type='button';
 if(copy.matches('button,a'))copy.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();if(source.isConnected&&!source.disabled)source.click();scheduleRefresh(30)});
 if(copy.matches('input,select,textarea')){
  const sync=type=>{if(!source.isConnected)return;if('checked'in source)source.checked=copy.checked;if(source.matches('select[multiple]'))[...source.options].forEach((option,index)=>{option.selected=!!copy.options[index]?.selected});else source.value=copy.value;source.dispatchEvent(new Event(type,{bubbles:true}));scheduleRefresh(30)};
  copy.addEventListener('input',()=>sync('input'));copy.addEventListener('change',()=>sync('change'));
 }
}
function copyCell(cell,key){
 const box=document.createElement('span');box.className='phone-cell-copy-v232';box.innerHTML=cell.innerHTML;stripDuplicateIds(box);
 const originals=[...cell.querySelectorAll('button,a,input,select,textarea')],copies=[...box.querySelectorAll('button,a,input,select,textarea')];copies.forEach((copy,index)=>{if(originals[index])proxyControl(copy,originals[index],key)});
 return box;
}
function makeResponsiveTable(table){
 const wrap=table.closest('.table-wrap');
 if(!wrap||wrap.classList.contains('desktop-data-table')||table.matches('.quarter-table')||table.closest('.game-sim-card,.live-center')||table.dataset.mobileCardsDisabled==='true')return;
 const headers=[...table.querySelectorAll('thead th')].map((th,index)=>textOf(th)||`Detail ${index+1}`),rows=[...table.querySelectorAll('tbody tr')].filter(row=>!row.hidden&&!row.classList.contains('hidden')&&row.style.display!=='none');
 const key=table.dataset.mobileTableKeyV232||(table.dataset.mobileTableKeyV232=`phone-table-${++tableSequence}`);
 let deck=wrap.parentElement?.querySelector(`:scope > .mobile-table-cards-v232[data-table-key="${key}"]`);
 if(!headers.length||!rows.length){deck?.remove();wrap.classList.remove('has-mobile-cards-v232');delete wrap.dataset.mobileCardCount;tableViews.delete(table);return}
 if(!deck){deck=document.createElement('div');deck.className='mobile-table-cards-v232';deck.dataset.tableKey=key;wrap.after(deck)}
 const markup=table.innerHTML,previous=tableViews.get(table),controls=[...table.querySelectorAll('button,a,input,select,textarea')];
 // Updating live values in place preserves the keyboard, selection, and focus.
 // Row/control identity also catches a source rerender with identical HTML.
 if(previous?.deck===deck&&previous.markup===markup&&previous.rows.length===rows.length&&previous.rows.every((row,index)=>row===rows[index])&&previous.controls.length===controls.length&&previous.controls.every((control,index)=>control===controls[index])){
  deck.querySelectorAll('button,a,input,select,textarea').forEach(copy=>{const source=controlSources.get(copy);if(source)syncControl(copy,source)});return;
 }
 const focused=deck.contains(document.activeElement)?document.activeElement:null,focusedSource=focused&&controlSources.get(focused),focusedIndex=previous?.controls.indexOf(focusedSource)??-1;
 const selection=focused&&typeof focused.selectionStart==='number'?[focused.selectionStart,focused.selectionEnd]:null;
 const cards=rows.map((row,rowIndex)=>{
  const cells=[...row.children],card=document.createElement('article');card.className='mobile-table-card-v232';card.dataset.row=String(rowIndex);if(!cells.length)return card;
  const primary=tablePrimary(headers,cells),rank=tableRank(headers,cells,primary),head=document.createElement('header');head.className=rank>=0?'mobile-table-head-v232':'mobile-table-head-v232 no-rank';
  if(rank>=0){const badge=document.createElement('span');badge.className='mobile-table-rank-v232';badge.append(copyCell(cells[rank],key));head.append(badge)}
  const title=document.createElement('div');title.className='mobile-table-title-v232';title.append(copyCell(cells[primary],key));const kicker=document.createElement('small');kicker.textContent=headers[primary]||'Entry';title.append(kicker);head.append(title);card.append(head);
  const grid=document.createElement('div');grid.className='mobile-table-grid-v232';cells.forEach((cell,index)=>{
   if(index===primary||index===rank)return;const control=cell.querySelector('button,a,input,select,textarea');if(!textOf(cell)&&!control)return;
   const item=document.createElement('div');item.className=control?'mobile-table-detail-v232 has-control':'mobile-table-detail-v232';if(cell.colSpan>1)item.classList.add('wide');
   const label=document.createElement('small');label.textContent=headers[index]||`Detail ${index+1}`;const content=copyCell(cell,key);content.querySelectorAll('input,select,textarea').forEach(copy=>{if(!copy.getAttribute('aria-label')&&!copy.getAttribute('aria-labelledby'))copy.setAttribute('aria-label',`${label.textContent}: ${textOf(cells[primary])}`)});item.append(label,content);grid.append(item);
  });
  card.append(grid);return card;
 });
 deck.replaceChildren(...cards);tableViews.set(table,{deck,markup,rows,controls});wrap.classList.add('has-mobile-cards-v232');wrap.dataset.mobileCardCount=String(cards.length);
 if(focusedSource){const target=controls.includes(focusedSource)?focusedSource:controls[focusedIndex];const replacement=[...deck.querySelectorAll('button,a,input,select,textarea')].find(copy=>controlSources.get(copy)===target);if(replacement&&!replacement.disabled){replacement.focus({preventScroll:true});if(selection&&replacement.setSelectionRange)try{replacement.setSelectionRange(...selection)}catch{}}}
}
function polishTables(root=activeScreen()||document){
 for(const host of new Set([root,$('modalBody')].filter(Boolean))){
  host.querySelectorAll?.('.mobile-table-cards-v232').forEach(deck=>{const wrap=deck.previousElementSibling;if(!wrap?.querySelector(`table[data-mobile-table-key-v232="${deck.dataset.tableKey}"]`))deck.remove()});
  host.querySelectorAll?.('.table-wrap table').forEach(makeResponsiveTable);
 }
}

