 const label=picker.closest('.depth-position-picker-v229');label?.classList.add('phone-depth-picker-v232');const copy=label?.querySelector(':scope > span');if(copy&&copy.textContent!=='POSITION / GROUP')copy.textContent='POSITION / GROUP';
